INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,40,'Taa-Haa','إِذۡ تَمۡشِيٓ أُخۡتُكَ فَتَقُولُ هَلۡ أَدُلُّكُمۡ عَلَىٰ مَن يَكۡفُلُهُۥۖ فَرَجَعۡنَٰكَ إِلَىٰٓ أُمِّكَ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَۚ وَقَتَلۡتَ نَفۡسࣰ ا فَنَجَّيۡنَٰكَ مِنَ ٱلۡغَمِّ وَفَتَنَّٰكَ فُتُونࣰ اۚ فَلَبِثۡتَ سِنِينَ فِيٓ أَهۡلِ مَدۡيَنَ ثُمَّ جِئۡتَ عَلَىٰ قَدَرࣲ يَٰمُوسَىٰ','جب تمہاری بہن (فرعون کے ہاں) گئی اور کہنے لگی کہ میں تمہیں ایسا شخص بتاؤں جو اس کو پالے۔ تو (اس طریق سے) ہم نے تم کو تمہاری ماں کے پاس پہنچا دیا تاکہ ان کی آنکھیں ٹھنڈی ہوں اور وہ رنج نہ کریں۔ اور تم نے ایک شخص کو مار ڈالا تو ہم نے تم کو غم سے مخلصی دی اور ہم نے تمہاری (کئی بار) آزمائش کی۔ پھر تم کئی سال اہل مدین میں ٹھہرے رہے۔ پھر اے موسیٰ تم (قابلیت رسالت کے) اندازے پر آ پہنچے','˹Remember˺ when your sister came along and proposed, ‘Shall I direct you to someone who will nurse him?’ So We reunited you with your mother so that her heart would be put at ease, and she would not grieve. ˹Later˺ you killed a man ˹by mistake˺, but We saved you from sorrow, as well as other tests We put you through. Then you stayed for a number of years among the people of Midian. Then you came here as pre-destined, O Moses','(उस वक्त) ज़ब तुम्हारी बहन चली (और फिर उनके घर में आकर) कहने लगी कि कहो तो मैं तुम्हें ऐसी दाया बताऊँ कि जो इसे अच्छी तरह पाले तो (इस तदबीर से) हमने फिर तुमको तुम्हारी माँ के पास पहुँचा दिया ताकि उसकी ऑंखें ठन्डी रहें और तुम्हारी (जुदाई पर) कुढ़े नहीं और तुमने एक शख्स (क़िबती) को मार डाला था और सख्त परेशान थे तो हमने तुमको (इस) ग़म से नजात दी और हमने तुम्हारा अच्छी तरह इम्तिहान कर लिया फिर तुम कई बरस तक मदयन के लोगों में जाकर रहे ऐ मूसा फिर तुम (उम्र के) एक अन्दाजे पर आ गए नबूवत के क़ायल हुए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,41,'Taa-Haa','وَٱصۡطَنَعۡتُكَ لِنَفۡسِي','اور میں نے تم کو اپنے (کام کے) لئے بنایا ہے','And I have selected you for My service','और मैंने तुमको अपनी रिसालत के वास्ते मुन्तख़िब किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,42,'Taa-Haa','ٱذۡهَبۡ أَنتَ وَأَخُوكَ بِـَٔايَٰتِي وَلَا تَنِيَا فِي ذِكۡرِي','تو تم اور تمہارا بھائی دونوں ہماری نشانیاں لے کر جاؤ اور میری یاد میں سستی نہ کرنا','Go forth, you and your brother, with My signs and never falter in remembering Me','तुम अपने भाई समैत हमारे मौजिज़े लेकर जाओ और (देखो) मेरी याद में सुस्ती न करना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,43,'Taa-Haa','ٱذۡهَبَآ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ','دونوں فرعون کے پاس جاؤ وہ سرکش ہو رہا ہے','Go, both of you, to Pharaoh, for he has truly transgressed ˹all bounds˺','तुम दोनों फिरऔन के पास जाओ बेशक वह बहुत सरकश हो गया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,44,'Taa-Haa','فَقُولَا لَهُۥ قَوۡلࣰ ا لَّيِّنࣰ ا لَّعَلَّهُۥ يَتَذَكَّرُ أَوۡ يَخۡشَىٰ','اور اس سے نرمی سے بات کرنا شاید وہ غور کرے یا ڈر جائے','Speak to him gently, so perhaps he may be mindful ˹of Me˺ or fearful ˹of My punishment˺.”','फिर उससे (जाकर) नरमी से बातें करो ताकि वह नसीहत मान ले या डर जाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,45,'Taa-Haa','قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفۡرُطَ عَلَيۡنَآ أَوۡ أَن يَطۡغَىٰ','دونوں کہنے لگے کہ ہمارے پروردگار ہمیں خوف ہے کہ ہم پر تعدی کرنے لگے یا زیادہ سرکش ہوجائے','They both pleaded, “Our Lord! We fear that he may be quick to harm us or act tyrannically.”','दोनों ने अर्ज़ की ऐ हमारे पालने वाले हम डरते हैं कि कहीं वह हम पर ज्यादती (न) कर बैठे या ज्यादा सरकशी कर ले');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,46,'Taa-Haa','قَالَ لَا تَخَافَآۖ إِنَّنِي مَعَكُمَآ أَسۡمَعُ وَأَرَىٰ','خدا نے فرمایا کہ ڈرو مت میں تمہارے ساتھ ہوں (اور) سنتا اور دیکھتا ہوں','Allah reassured ˹them˺, “Have no fear! I am with you, hearing and seeing','फ़रमाया तुम डरो नहीं मैं तुम्हारे साथ हूँ (सब कुछ) सुनता और देखता हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,47,'Taa-Haa','فَأۡتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَٰٓءِيلَ وَلَا تُعَذِّبۡهُمۡۖ قَدۡ جِئۡنَٰكَ بِـَٔايَةࣲ مِّن رَّبِّكَۖ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلۡهُدَىٰٓ','(اچھا) تو اس کے پاس جاؤ اور کہو کہ ہم آپ کے پروردگار کے بھیجے ہوئے ہیں تو بنی اسرائیل کو ہمارے ساتھ جانے کی اجازت دیجیئے۔ اور انہیں عذاب نہ کیجیئے۔ ہم آپ کے پاس آپ کے پروردگار کی طرف سے نشانی لے کر آئے ہیں۔ اور جو ہدایت کی بات مانے اس کو سلامتی ہو','So go to him and say, ‘Indeed we are both messengers from your Lord, so let the Children of Israel go with us, and do not oppress them. We have come to you with a sign from your Lord. And salvation will be for whoever follows the ˹right˺ guidance','ग़रज़ तुम दोनों उसके पास जाओ और कहो कि हम आप के परवरदिगार के रसूल हैं तो बनी इसराइल को हमारे साथ भेज दीजिए और उन्हें सताइए नहीं हम आपके पास आपके परवरदिगार का मौजिज़ा लेकर आए हैं और जो राहे रास्त की पैरवी करे उसी के लिए सलामती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,48,'Taa-Haa','إِنَّا قَدۡ أُوحِيَ إِلَيۡنَآ أَنَّ ٱلۡعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ','ہماری طرف یہ وحی آئی ہے کہ جو جھٹلائے اور منہ پھیرے اس کے لئے عذاب (تیار) ہے','It has indeed been revealed to us that the punishment will be upon whoever denies ˹the truth˺ and turns away.’”','हमारे पास खुदा की तरफ से ये ''''वही'''' नाज़िल हुईहै कि यक़ीनन अज़ाब उसी शख्स पर है जो (खुदा की आयतों को) झुठलाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,49,'Taa-Haa','قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ','(غرض موسیٰ اور ہارون فرعون کے پاس گئے) اس نے کہا کہ موسیٰ تمہارا پروردگار کون ہے؟','Pharaoh asked, “Who then is the Lord of you two, O Moses?”','और उसके हुक्म से मुँह मोड़े (ग़रज़ गए और कहा) फिरऔन ने पूछा ऐ मूसा आख़िर तुम दोनों का परवरदिगार कौन है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,50,'Taa-Haa','قَالَ رَبُّنَا ٱلَّذِيٓ أَعۡطَىٰ كُلَّ شَيۡءٍ خَلۡقَهُۥ ثُمَّ هَدَىٰ','کہا کہ ہمارا پروردگار وہ ہے جس نے ہر چیز کو اس کی شکل وصورت بخشی پھر راہ دکھائی','He answered, “Our Lord is the One Who has given everything its ˹distinctive˺ form, then guided ˹it˺.”','मूसा ने कहा हमारा परवरदिगार वह है जिसने हर चीज़ को उसके (मुनासिब) सूरत अता फरमाई');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,51,'Taa-Haa','قَالَ فَمَا بَالُ ٱلۡقُرُونِ ٱلۡأُولَىٰ','کہا تو پہلی جماعتوں کا کیا حال؟','Pharaoh asked, “And what about previous peoples?”','फिर उसी ने ज़िन्दगी बसर करने के तरीक़े बताए फिरऔन ने पूछा भला अगले लोगों का हाल (तो बताओ) कि क्या हुआ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,52,'Taa-Haa','قَالَ عِلۡمُهَا عِندَ رَبِّي فِي كِتَٰبࣲۖ لَّا يَضِلُّ رَبِّي وَلَا يَنسَى','کہا کہ ان کا علم میرے پروردگار کو ہے (جو) کتاب میں (لکھا ہوا ہے) ۔ میرا پروردگار نہ چوکتا ہے نہ بھولتا ہے','He replied, “That knowledge is with my Lord in a Record. My Lord neither falters nor forgets ˹anything˺.”','मूसा ने कहा इन बातों का इल्म मेरे परवरदिगार के पास एक किताब (लौहे महफूज़) में (लिखा हुआ) है मेरा परवरदिगार न बहकता है न भूलता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,53,'Taa-Haa','ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدࣰ ا وَسَلَكَ لَكُمۡ فِيهَا سُبُلࣰ ا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءࣰ فَأَخۡرَجۡنَا بِهِۦٓ أَزۡوَٰجࣰ ا مِّن نَّبَاتࣲ شَتَّىٰ','وہ (وہی تو ہے) جس نے تم لوگوں کے لئے زمین کو فرش بنایا اور اس میں تمہارے لئے رستے جاری کئے اور آسمان سے پانی برسایا۔ پھر اس سے انواع واقسام کی مختلف روئیدگیاں پیدا کیں','˹He is the One˺ Who has laid out the earth for ˹all of˺ you, and set in it pathways for you, and sends down rain from the sky, causing various types of plants to grow','वह वही है जिसने तुम्हारे (फ़ायदे के) वास्ते ज़मीन को बिछौना बनाया और तुम्हारे लिए उसमें राहें निकाली और उसी ने आसमान से पानी बरसाया फिर (खुदा फरमाता है कि) हम ही ने उस पानी के ज़रिए से मुख्तलिफ़ क़िस्मों की घासे निकाली');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,54,'Taa-Haa','كُلُواْ وَٱرۡعَوۡاْ أَنۡعَٰمَكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّأُوْلِي ٱلنُّهَىٰ','کہ (خود بھی) کھاؤ اور اپنے چارپایوں کو بھی چراؤ۔ بےشک ان (باتوں) میں عقل والوں کے لئے (بہت سی) نشانیاں ہیں','˹so˺ eat and graze your cattle. Surely in this are signs for people of sound judgment','(ताकि) तुम खुद भी खाओ और अपने चारपायों को भी चराओ कुछ शक नहीं कि इसमें अक्लमन्दों के वास्ते (क़ुदरते खुदा की) बहुत सी निशानियाँ हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,55,'Taa-Haa','۞مِنۡهَا خَلَقۡنَٰكُمۡ وَفِيهَا نُعِيدُكُمۡ وَمِنۡهَا نُخۡرِجُكُمۡ تَارَةً أُخۡرَىٰ','اسی (زمین) سے ہم تم کو پیدا کیا اور اسی میں تمہیں لوٹائیں گے اور اسی سے دوسری دفعہ نکالیں گے','From the earth We created you, and into it We will return you, and from it We will bring you back again','हमने इसी ज़मीन से तुम को पैदा किया और (मरने के बाद) इसमें लौटा कर लाएँगे और उसी से दूसरी बार (क़यामत के दिन) तुमको निकाल खड़ा करेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,56,'Taa-Haa','وَلَقَدۡ أَرَيۡنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ','اور ہم نے فرعون کو اپنی سب نشانیاں دکھائیں مگر وہ تکذیب وانکار ہی کرتا رہا','And We certainly showed Pharaoh all of Our signs, but he denied them and refused ˹to believe˺','और मैंने फिरऔन को अपनी सारी निशानियाँ दिखा दी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,57,'Taa-Haa','قَالَ أَجِئۡتَنَا لِتُخۡرِجَنَا مِنۡ أَرۡضِنَا بِسِحۡرِكَ يَٰمُوسَىٰ','کہنے لگا کہ موسیٰ تم ہمارے پاس اس لئے آئے ہو کہ اپنے جادو (کے زور) سے ہمیں ہمارے ملک سے نکال دو','He said, “Have you come to drive us out of our land with your magic, O Moses','इस पर भी उसने सबको झुठला दिया और न माना (और) कहने लगा ऐ मूसा क्या तुम हमारे पास इसलिए आए हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,58,'Taa-Haa','فَلَنَأۡتِيَنَّكَ بِسِحۡرࣲ مِّثۡلِهِۦ فَٱجۡعَلۡ بَيۡنَنَا وَبَيۡنَكَ مَوۡعِدࣰ ا لَّا نُخۡلِفُهُۥ نَحۡنُ وَلَآ أَنتَ مَكَانࣰ ا سُوࣰ ى','تو ہم بھی تمہارے مقابل ایسا ہی جادو لائیں گے تو ہمارے اور اپنے درمیان ایک وقت مقرر کر لو کہ نہ تو ہم اس کے خلاف کریں اور نہ تم (اور یہ مقابلہ) ایک ہموار میدان میں (ہوگا)','We can surely meet you with similar magic. So set for us an appointment that neither of us will fail to keep, in a central place.”','कि हम को हमारे मुल्क (मिस्र से) अपने जादू के ज़ोर से निकाल बाहर करो अच्छा तो (रहो) हम भी तुम्हारे सामने ऐसा जादू पेश करते हैं फिर तुम अपने और हमारे दरमियान एक वक्त मुक़र्रर करो कि न हम उसके ख़िलाफ करे और न तुम और मुक़ाबला एक साफ़ खुले मैदान में हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,59,'Taa-Haa','قَالَ مَوۡعِدُكُمۡ يَوۡمُ ٱلزِّينَةِ وَأَن يُحۡشَرَ ٱلنَّاسُ ضُحࣰ ى','موسیٰ نے کہا آپ کے لئے (مقابلے کا) دن نو روز (مقرر کیا جاتا ہے) اور یہ کہ لوگ اس دن چاشت کے وقت اکھٹے ہوجائیں','Moses said, “Your appointment is on the Day of the Festival, and let the people be gathered mid-morning.”','मूसा ने कहा तुम्हारे (मुक़ाबले) की मीयाद ज़ीनत (ईद) का दिन है और उस रोज़ सब लोग दिन चढ़े जमा किए जाँए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,60,'Taa-Haa','فَتَوَلَّىٰ فِرۡعَوۡنُ فَجَمَعَ كَيۡدَهُۥ ثُمَّ أَتَىٰ','تو فرعون لوٹ گیا اور اپنے سامان جمع کرکے پھر آیا','Pharaoh then withdrew, orchestrated his scheme, then returned','उसके बाद फिरऔन (अपनी जगह) लौट गया फिर अपने चलत्तर (जादू के सामान) जमा करने लगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,61,'Taa-Haa','قَالَ لَهُم مُّوسَىٰ وَيۡلَكُمۡ لَا تَفۡتَرُواْ عَلَى ٱللَّهِ كَذِبࣰ ا فَيُسۡحِتَكُم بِعَذَابࣲۖ وَقَدۡ خَابَ مَنِ ٱفۡتَرَىٰ','موسیٰ نے ان (جادوگروں) سے کہا کہ ہائے تمہاری کمبختی۔ خدا پر جھوٹ افتراء نہ کرو کہ وہ تمہیں عذاب سے فنا کردے گا اور جس نے افتراء کیا وہ نامراد رہا','Moses warned the magicians, “Woe to you! Do not fabricate a lie against Allah, or He will wipe you out with a torment. Whoever fabricates ˹lies˺ is bound to fail.”','फिर (मुक़ाबले को) आ मौजूद हुआ मूसा ने (फ़िरऔनियों से) कहा तुम्हारा नास हो खुदा पर झूठी-झूठी इफ्तेरा परदाज़ियाँ न करो वरना वह अज़ाब (नाज़िल करके) इससे तुम्हारा मटियामेट कर छोड़ेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,62,'Taa-Haa','فَتَنَٰزَعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ وَأَسَرُّواْ ٱلنَّجۡوَىٰ','تو وہ باہم اپنے معاملے میں جھگڑانے اور چپکے چپکے سرگوشی کرنے لگے','So the magicians disputed the matter among themselves, conversing privately','और (याद रखो कि) जिसने इफ्तेरा परदाज़ियाँ न की वह यकीनन नामुराद रहा उस पर वह लोग अपने काम में बाहम झगड़ने और सरगोशियाँ करने लगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,63,'Taa-Haa','قَالُوٓاْ إِنۡ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخۡرِجَاكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِمَا وَيَذۡهَبَا بِطَرِيقَتِكُمُ ٱلۡمُثۡلَىٰ','کہنے لگے یہ دونوں جادوگر ہیں چاہتے ہیں کہ اپنے جادو (کے زور) سے تم کو تمہارے ملک سے نکل دیں اور تمہارے شائستہ مذہب کو نابود کردیں','They concluded, “These two are only magicians who want to drive you out of your land with their magic, and do away with your most cherished traditions','(आख़िर) वह लोग बोल उठे कि ये दोनों यक़ीनन जादूगर हैं और चाहते हैं कि अपने जादू (के ज़ोर) से तुम लोगों को तुम्हारे मुल्क से निकाल बाहर करें और तुम्हारे अच्छे ख़ासे मज़हब को मिटा छोड़ें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,64,'Taa-Haa','فَأَجۡمِعُواْ كَيۡدَكُمۡ ثُمَّ ٱئۡتُواْ صَفࣰّ اۚ وَقَدۡ أَفۡلَحَ ٱلۡيَوۡمَ مَنِ ٱسۡتَعۡلَىٰ','تو تم (جادو کا) سامان اکھٹا کرلو اور پھر قطار باندھ کر آؤ۔ آج جو غالب رہا وہی کامیاب ہوا','So orchestrate your plan, then come forward in ˹perfect˺ ranks. And whoever prevails today will certainly be successful.”','तो तुम भी खूब अपने चलत्तर (जादू वग़ैरह) दुरूस्त कर लो फिर परा (सफ़) बाँध के (उनके मुक़ाबले में) आ पड़ो और जो आज डर रहा हो वही फायज़ुलहराम रहा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,65,'Taa-Haa','قَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنۡ أَلۡقَىٰ','بولے کہ موسیٰ یا تم (اپنی چیز) ڈالو یا ہم (اپنی چیزیں) پہلے ڈالتے ہیں','They said, “O Moses! Either you cast, or let us be the first to cast.”','ग़रज़ जादूगरों ने कहा (ऐ मूसा) या तो तुम ही (अपने जादू) फेंको और या ये कि पहले जो जादू फेंके वह हम ही हों');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,66,'Taa-Haa','قَالَ بَلۡ أَلۡقُواْۖ فَإِذَا حِبَالُهُمۡ وَعِصِيُّهُمۡ يُخَيَّلُ إِلَيۡهِ مِن سِحۡرِهِمۡ أَنَّهَا تَسۡعَىٰ','موسیٰ نے کہا نہیں تم ہی ڈالو۔ (جب انہوں نے چیزیں ڈالیں) تو ناگہاں ان کی رسیاں اور لاٹھیاں موسی کے خیال میں ایسی آنے لگیں کہ وہ (میدان) میں ادھر اُدھر دوڑ رہی ہیں','Moses responded, “No, you go first.” And suddenly their ropes and staffs appeared to him—by their magic—to be slithering','मूसा ने कहा (मैं नहीं डालूँगा) बल्कि तुम ही पहले डालो (ग़रज़ उन्होंने अपने करतब दिखाए) तो बस मूसा को उनके जादू (के ज़ोर से) ऐसा मालूम हुआ कि उनकी रस्सियाँ और उनकी छड़ियाँ दौड़ रही हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,67,'Taa-Haa','فَأَوۡجَسَ فِي نَفۡسِهِۦ خِيفَةࣰ مُّوسَىٰ','(اُس وقت) موسیٰ نے اپنے دل میں خوف معلوم کیا','So Moses concealed fear within himself','तो मूसा ने अपने दिल में कुछ दहशत सी पाई');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,68,'Taa-Haa','قُلۡنَا لَا تَخَفۡ إِنَّكَ أَنتَ ٱلۡأَعۡلَىٰ','ہم نے کہا خوف نہ کرو بلاشبہ تم ہی غالب ہو','We reassured ˹him˺, “Do not fear! It is certainly you who will prevail','हमने कहा (मूसा) इस से डरो नहीं यक़ीनन तुम ही वर रहोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,69,'Taa-Haa','وَأَلۡقِ مَا فِي يَمِينِكَ تَلۡقَفۡ مَا صَنَعُوٓاْۖ إِنَّمَا صَنَعُواْ كَيۡدُ سَٰحِرࣲۖ وَلَا يُفۡلِحُ ٱلسَّاحِرُ حَيۡثُ أَتَىٰ','اور جو چیز (یعنی لاٹھی) تمہارے داہنے ہاتھ میں ہے اسے ڈال دو کہ جو کچھ انہوں نے بنایا ہے اس کو نگل جائے گی۔ جو کچھ انہوں نے بنایا ہے (یہ تو) جادوگروں کے ہتھکنڈے ہیں اور جادوگر جہاں جائے فلاح نہیں پائے گا','Cast what is in your right hand, and it will swallow up what they have made, for what they have made is no more than a magic trick. And magicians can never succeed wherever they go.”','और तुम्हारे दाहिने हाथ में जो (लाठी) है उसे डाल तो दो कि जो करतब उन लोगों ने की है उसे हड़प कर जाए क्योंकि उन लोगों ने जो कुछ करतब की वह एक जादूगर की करतब है और जादूगर जहाँ जाए कामयाब नहीं हो सकता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,70,'Taa-Haa','فَأُلۡقِيَ ٱلسَّحَرَةُ سُجَّدࣰ ا قَالُوٓاْ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ','(القصہ یوں ہی ہوا) تو جادوگر سجدے میں گر پڑے (اور) کہنے لگے کہ ہم موسیٰ اور ہارون کے پروردگار پر ایمان لائے','So the magicians fell down in prostration, declaring, “We believe in the Lord of Aaron and Moses.”','(ग़रज मूसा की लाटी ने) सब हड़प कर लिया (ये देखते ही) वह सब जादूगर सजदे में गिर पड़े (और कहने लगे) कि हम मूसा और हारून के परवरदिगार पर ईमान ले आए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,71,'Taa-Haa','قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَۖ فَلَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفࣲ وَلَأُصَلِّبَنَّكُمۡ فِي جُذُوعِ ٱلنَّخۡلِ وَلَتَعۡلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابࣰ ا وَأَبۡقَىٰ','(فرعون) بولا کہ پیشتر اس کے میں تمہیں اجازت دوں تم اس پر ایمان لے آئے۔ بےشک وہ تمہارا بڑا (یعنی استاد) ہے جس نے تم کو جادو سکھایا ہے۔ سو میں تمہارے ہاتھ اور پاؤں (جانب) خلاف سے کٹوا دوں گا اور کھجور کے تنوں پر سولی چڑھوا دوں گا (اس وقت) تم کو معلوم ہوگا کہ ہم میں سے کس کا عذاب زیادہ سخت اور دیر تک رہنے والا ہے','Pharaoh threatened, “How dare you believe in him before I give you permission? He must be your master who taught you magic. I will certainly cut off your hands and feet on opposite sides, and crucify you on the trunks of palm trees. You will really see whose punishment is more severe and more lasting.”','फिरऔन ने उन लोगों से कहा (हाए) इससे पहले कि हम तुमको इजाज़त दें तुम उस पर ईमान ले आए इसमें शक नहीं कि ये तुम सबका बड़ा (गुरू) है जिसने तुमको जादू सिखाया है तो मैं तुम्हारा एक तरफ़ के हाथ और दूसरी तरफ़ के पाँव ज़रूर काट डालूँगा और तुम्हें यक़ीनन खुरमे की शाख़ों पर सूली चढ़ा दूँगा और उस वक्त तुमको (अच्छी तरह) मालूम हो जाएगा कि हम (दोनों) फरीक़ों से अज़ाब में ज्यादा बढ़ा हुआ कौन और किसको क़याम ज्यादा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,72,'Taa-Haa','قَالُواْ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلۡبَيِّنَٰتِ وَٱلَّذِي فَطَرَنَاۖ فَٱقۡضِ مَآ أَنتَ قَاضٍۖ إِنَّمَا تَقۡضِي هَٰذِهِ ٱلۡحَيَوٰةَ ٱلدُّنۡيَآ','انہوں نے کہا جو دلائل ہمارے پاس آگئے ہیں ان پر اور جس نے ہم کو پیدا ہے اس پر ہم آپ کو ہرگز ترجیح نہیں دیں گے تو آپ کو جو حکم دینا ہو دے دیجیئے۔ اور آپ (جو) حکم دے سکتے ہیں وہ صرف اسی دنیا کی زندگی میں (دے سکتے ہیں)','They responded, “By the One Who created us! We will never prefer you over the clear proofs that have come to us. So do whatever you want! Your authority only covers the ˹fleeting˺ life of this world','जादूगर बोले कि ऐसे वाजेए व रौशन मौजिज़ात जो हमारे सामने आए उन पर और जिस (खुदा) ने हमको पैदा किया उस पर तो हम तुमको किसी तरह तरजीह नहीं दे सकते तो जो तुझे करना हो कर गुज़र तो बस दुनिया की (इसी ज़रा) ज़िन्दगी पर हुकूमत कर सकता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,73,'Taa-Haa','إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغۡفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكۡرَهۡتَنَا عَلَيۡهِ مِنَ ٱلسِّحۡرِۗ وَٱللَّهُ خَيۡرࣱ وَأَبۡقَىٰٓ','ہم اپنے پروردگار پر ایمان لے آئے تاکہ وہ ہمارے گناہوں کو معاف کرے اور (اسے بھی) جو آپ نے ہم سے زبردستی جادو کرایا۔ اور خدا بہتر اور باقی رہنے والا ہے','Indeed, we have believed in our Lord so He may forgive our sins and that magic you have forced us to practice. And Allah is far superior ˹in reward˺ and more lasting ˹in punishment˺.”','(और कहा) हम तो अपने परवरदिगार पर इसलिए ईमान लाए हैं ताकि हमारे वास्ते सारे गुनाह माफ़ कर दे और (ख़ास कर) जिस पर तूने हमें मजबूर किया था और खुदा ही सबसे बेहतर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,74,'Taa-Haa','إِنَّهُۥ مَن يَأۡتِ رَبَّهُۥ مُجۡرِمࣰ ا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ','جو شخص اپنے پروردگار کے پاس گنہگار ہو کر آئے گا تو اس کے لئے جہنم ہے۔ جس میں نہ مرے گا نہ جیئے گا','Whoever comes to their Lord as an evildoer will certainly have Hell, where they can neither live nor die','और (उसी को) सबसे ज्यादा क़याम है इसमें शक नहीं कि जो शख्स मुजरिम होकर अपने परवरदिगार के सामने हाज़िर होगा तो उसके लिए यक़ीनन जहन्नुम (धरा हुआ) है जिसमें न तो वह मरे ही गा और न ज़िन्दा ही रहेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,75,'Taa-Haa','وَمَن يَأۡتِهِۦ مُؤۡمِنࣰ ا قَدۡ عَمِلَ ٱلصَّٰلِحَٰتِ فَأُوْلَٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلۡعُلَىٰ','اور جو اس کے روبرو ایماندار ہو کر آئے گا اور عمل بھی نیک کئے ہوں گے تو ایسے لوگوں کے لئے اونچے اونچے درجے ہیں','But whoever comes to Him as a believer, having done good, they will have the highest ranks','(सिसकता रहेगा) और जो शख्स उसके सामने ईमानदार हो कर हाज़िर होगा और उसने अच्छे-अच्छे काम भी किए होंगे तो ऐसे ही लोग हैं जिनके लिए बड़े-बड़े बुलन्द रूतबे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,76,'Taa-Haa','جَنَّٰتُ عَدۡنࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ','(یعنی) ہمیشہ رہنے کے باغ جن کے نیچے نہریں بہہ رہی ہیں۔ ہمیشہ ان میں رہیں گے۔ اور یہ اس شخص کا بدلہ ہے جو پاک ہوا','the Gardens of Eternity, under which rivers flow, where they will stay forever. That is the reward of those who purify themselves','वह सदाबहार बाग़ात जिनके नीचे नहरें जारी हैं वह लोग उसमें हमेशा रहेंगे और जो गुनाह से पाक व पाकीज़ा रहे उस का यही सिला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,77,'Taa-Haa','وَلَقَدۡ أَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِي فَٱضۡرِبۡ لَهُمۡ طَرِيقࣰ ا فِي ٱلۡبَحۡرِ يَبَسࣰ ا لَّا تَخَٰفُ دَرَكࣰ ا وَلَا تَخۡشَىٰ','اور ہم نے موسیٰ کی طرف وحی بھیجی کہ ہمارے بندوں کو راتوں رات نکال لے جاؤ پھر ان کے لئے دریا میں (لاٹھی مار کر) خشک رستہ بنا دو پھر تم کو نہ تو (فرعون کے) آپکڑنے کا خوف ہوگا اور نہ (غرق ہونے کا) ڈر','And We surely inspired Moses, ˹saying,˺ “Leave with My servants ˹at night˺ and strike a dry passage for them across the sea. Have no fear of being overtaken, nor be concerned ˹of drowning˺.”','और हमने मूसा के पास ''''वही'''' भेजी कि मेरे बन्दों (बनी इसराइल) को (मिस्र से) रातों रात निकाल ले जाओ फिर दरिया में (लाठी मारकर) उनके लिए एक सूखी राह निकालो और तुमको पीछा करने का न कोई खौफ़ रहेगा न (डूबने की) कोई दहशत');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,78,'Taa-Haa','فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلۡيَمِّ مَا غَشِيَهُمۡ','پھر فرعون نے اپنے لشکر کے ساتھ ان کا تعاقب کیا تو دریا (کی موجوں) نے ان پر چڑھ کر انہیں ڈھانک لیا (یعنی ڈبو دیا)','Then Pharaoh pursued them with his soldiers—but how overwhelming were the waters that submerged them','ग़रज़ फिरऔन ने अपने लशकर समैत उनका पीछा किया फिर दरिया (के पानी का रेला) जैसा कुछ उन पर छाया गया वह छा गया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,79,'Taa-Haa','وَأَضَلَّ فِرۡعَوۡنُ قَوۡمَهُۥ وَمَا هَدَىٰ','اور فرعون نے اپنی قوم کو گمراہ کردیا اور سیدھے رستے پر نہ ڈالا','And ˹so˺ Pharaoh led his people astray, and did not guide ˹them rightly˺','और फिरऔन ने अपनी क़ौम को गुमराह (करके हलाक) कर डाला और उनकी हिदायत न की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,80,'Taa-Haa','يَٰبَنِيٓ إِسۡرَٰٓءِيلَ قَدۡ أَنجَيۡنَٰكُم مِّنۡ عَدُوِّكُمۡ وَوَٰعَدۡنَٰكُمۡ جَانِبَ ٱلطُّورِ ٱلۡأَيۡمَنَ وَنَزَّلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰ','اے آل یعقوب ہم نے تم کو تمہارے دشمن سے نجات دی اور تورات دینے کے لئے تم سے کوہ طور کی داہنی طرف مقرر کی اور تم پر من اور سلویٰ نازل کیا','O Children of Israel! We saved you from your enemy, and made an appointment with you on the right side of Mount Ṭûr, and sent down to you manna and quails','ऐ बनी इसराइल हमने तुमको तुम्हारे दुश्मन (के पंजे) से छुड़ाया और तुम से (कोहेतूर) के दाहिने तरफ का वायदा किया और हम ही ने तुम पर मन व सलवा नाज़िल किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,81,'Taa-Haa','كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَلَا تَطۡغَوۡاْ فِيهِ فَيَحِلَّ عَلَيۡكُمۡ غَضَبِيۖ وَمَن يَحۡلِلۡ عَلَيۡهِ غَضَبِي فَقَدۡ هَوَىٰ','(اور حکم دیا کہ) جو پاکیزہ چیزیں ہم نے تم کو دی ہیں ان کو کھاؤ۔ اور اس میں حد سے نہ نکلنا۔ ورنہ تم پر میرا غضب نازل ہوگا۔ اور جس پر میرا غضب نازل ہوا وہ ہلاک ہوگیا','˹saying,˺ “Eat from the good things We have provided for you, but do not transgress in them, or My wrath will befall you. And whoever My wrath befalls is certainly doomed','और (फ़रमाया) कि हमने जो पाक व पाक़ीज़ा रोज़ी तुम्हें दे रखी है उसमें से खाओ (पियो) और उसमें (किसी क़िस्म की) शरारत न करो वरना तुम पर मेरा अज़ाब नाज़िल हो जाएगा और (याद रखो कि) जिस पर मेरा ग़ज़ब नाज़िल हुआ तो वह यक़ीनन गुमराह (हलाक) हुआ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,82,'Taa-Haa','وَإِنِّي لَغَفَّارࣱ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحࣰ ا ثُمَّ ٱهۡتَدَىٰ','اور جو توبہ کرے اور ایمان لائے اور عمل نیک کرے پھر سیدھے رستے چلے اس کو میں بخش دینے والا ہوں','But I am truly Most Forgiving to whoever repents, believes, and does good, then persists on ˹true˺ guidance.”','और जो शख्स तौबा करे और ईमान लाए और अच्छे काम करे फिर साबित क़दम रहे तो हम उसको ज़रूर बख्शने वाले हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,83,'Taa-Haa','۞وَمَآ أَعۡجَلَكَ عَن قَوۡمِكَ يَٰمُوسَىٰ','اور اے موسیٰ تم نے اپنی قوم سے (آگے چلے آنے میں) کیوں جلدی کی','˹Allah asked,˺ “Why have you come with such haste ahead of your people, O Moses?”','फिर जब मूसा सत्तर आदमियों को लेकर चले और खुद बढ़ आए तो हमने कहा कि (ऐ मूसा तुमने अपनी क़ौम से आगे चलने में क्यों जल्दी की)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,84,'Taa-Haa','قَالَ هُمۡ أُوْلَآءِ عَلَىٰٓ أَثَرِي وَعَجِلۡتُ إِلَيۡكَ رَبِّ لِتَرۡضَىٰ','کہا وہ میرے پیچھے (آ رہے) ہیں اور اے پروردگار میں نے تیری طرف (آنے کی) جلدی اس لئے کی کہ تو خوش ہو','He replied, “They are close on my tracks. And I have hastened to You, my Lord, so You will be pleased.”','ग़रज़ की वह भी तो मेरे ही पीछे चले आ रहे हैं और इसी लिए मैं जल्दी करके तेरे पास इसलिए आगे बढ़ आया हूँ ताकि तू (मुझसे) खुश रहे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,85,'Taa-Haa','قَالَ فَإِنَّا قَدۡ فَتَنَّا قَوۡمَكَ مِنۢ بَعۡدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِيُّ','فرمایا کہ ہم نے تمہاری قوم کو تمہارے بعد آزمائش میں ڈال دیا ہے اور سامری نے ان کو بہکا دیا ہے','Allah responded, “We have indeed tested your people in your absence, and the Sâmiri has led them astray.”','फ़रमाया तो हमने तुम्हारे (आने के बाद) तुम्हारी क़ौम का इम्तिहान लिया और सामरी ने उनको गुमराह कर छोड़ा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,86,'Taa-Haa','فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفࣰ اۚ قَالَ يَٰقَوۡمِ أَلَمۡ يَعِدۡكُمۡ رَبُّكُمۡ وَعۡدًا حَسَنًاۚ أَفَطَالَ عَلَيۡكُمُ ٱلۡعَهۡدُ أَمۡ أَرَدتُّمۡ أَن يَحِلَّ عَلَيۡكُمۡ غَضَبࣱ مِّن رَّبِّكُمۡ فَأَخۡلَفۡتُم مَّوۡعِدِي','اور موسیٰ غصّے اور غم کی حالت میں اپنی قوم کے پاس واپس آئے (اور) کہنے لگے کہ اے قوم کیا تمہارے پروردگار نے تم سے ایک اچھا وعدہ نہیں کیا تھا؟ کیا (میری جدائی کی) مدت تمہیں دراز (معلوم) ہوئی یا تم نے چاہا کہ تم پر تمہارے پروردگار کی طرف سے غضب نازل ہو۔ اور (اس لئے) تم نے مجھ سے جو وعدہ کیا تھا (اس کے) خلاف کیا','So Moses returned to his people, furious and sorrowful. He said, “O my people! Had your Lord not made you a good promise? Has my absence been too long for you? Or have you wished for wrath from your Lord to befall you, so you broke your promise to me?”','(तो मूसा) गुस्से में भरे पछताए हुए अपनी क़ौम की तरफ पलटे और आकर कहने लगे ऐ मेरी (क़म्बख्त) क़ौम क्या तुमसे तुम्हारे परवरदिगार ने एक अच्छा वायदा (तौरेत देने का) न किया था तुम्हारे वायदे में अरसा लग गया या तुमने ये चाहा कि तुम पर तुम्हारे परवरदिगार का ग़ज़ब टूंट पड़े कि तुमने मेरे वायदे (खुदा की परसतिश) के ख़िलाफ किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,87,'Taa-Haa','قَالُواْ مَآ أَخۡلَفۡنَا مَوۡعِدَكَ بِمَلۡكِنَا وَلَٰكِنَّا حُمِّلۡنَآ أَوۡزَارࣰ ا مِّن زِينَةِ ٱلۡقَوۡمِ فَقَذَفۡنَٰهَا فَكَذَٰلِكَ أَلۡقَى ٱلسَّامِرِيُّ','وہ کہنے لگے کہ ہم نے اپنے اختیار سے تم سے وعدہ خلاف نہیں کیا۔ بلکہ ہم لوگوں کے زیوروں کا بوجھ اٹھائے ہوئے تھے۔ پھر ہم نے اس کو (آگ میں) ڈال دیا اور اسی طرح سامری نے ڈال دیا','They argued, “We did not break our promise to you of our own free will, but we were made to carry the burden of the people’s ˹golden˺ jewellery, then we threw it ˹into the fire˺, and so did the Sâmiri.”','वह लोग कहने लगे हमने आपके वायदे के ख़िलाफ नहीं किया बल्कि (बात ये हुईकि फिरऔन की) क़ौम के ज़ेवर के बोझे जो (मिस्र से निकलते वक्त) हम पर लोग गए थे उनको हम लोगों ने (सामरी के कहने से आग में) डाल दिया फिर सामरी ने भी डाल दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,88,'Taa-Haa','فَأَخۡرَجَ لَهُمۡ عِجۡلࣰ ا جَسَدࣰ ا لَّهُۥ خُوَارࣱ فَقَالُواْ هَٰذَآ إِلَٰهُكُمۡ وَإِلَٰهُ مُوسَىٰ فَنَسِيَ','تو اس نے ان کے لئے ایک بچھڑا بنا دیا (یعنی اس کا) قالب جس کی آواز گائے کی سی تھی۔ تو لوگ کہنے لگے کہ یہی تمہارا معبود ہے اور موسیٰ کا بھی معبود ہے۔ مگر وہ بھول گئے ہیں','Then he moulded for them an idol of a calf that made a lowing sound. They said, “This is your god and the god of Moses, but Moses forgot ˹where it was˺!”','फिर सामरी ने उन लोगों के लिए (उसी जेवर से) एक बछड़े की मूरत बनाई जिसकी आवाज़ भी बछड़े की सी थी उस पर बाज़ लोग कहने लगे यही तुम्हारा (भी) माबूद और मूसा का (भी) माबूद है मगर वह भूल गया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,89,'Taa-Haa','أَفَلَا يَرَوۡنَ أَلَّا يَرۡجِعُ إِلَيۡهِمۡ قَوۡلࣰ ا وَلَا يَمۡلِكُ لَهُمۡ ضَرࣰّ ا وَلَا نَفۡعࣰ ا','کیا یہ لوگ نہیں دیکھتے کہ وہ ان کی کسی بات کا جواب نہیں دیتا۔ اور نہ ان کے نقصان اور نفع کا کچھ اختیار رکھتا ہے','Did they not see that it did not respond to them, nor could it protect or benefit them','भला इनको इतनी भी न सूझी कि ये बछड़ा न तो उन लोगों को पलट कर उन की बात का जवाब ही देता है और न उनका ज़रर ही उस के हाथ में है और न नफ़ा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,90,'Taa-Haa','وَلَقَدۡ قَالَ لَهُمۡ هَٰرُونُ مِن قَبۡلُ يَٰقَوۡمِ إِنَّمَا فُتِنتُم بِهِۦۖ وَإِنَّ رَبَّكُمُ ٱلرَّحۡمَٰنُ فَٱتَّبِعُونِي وَأَطِيعُوٓاْ أَمۡرِي','اور ہارون نے ان سے پہلے ہی کہہ دیا تھا کہ لوگو اس سے صرف تمہاری آزمائش کی گئی ہے۔ اور تمہارا پروردگار تو خدا ہے تو میری پیروی کرو اور میرا کہا مانو','Aaron had already warned them beforehand, “O my people! You are only being tested by this, for indeed your ˹one true˺ Lord is the Most Compassionate. So follow me and obey my orders.”','और हारून ने उनसे पहले कहा भी था कि ऐ मेरी क़ौम तुम्हारा सिर्फ़ इसके ज़रिये से इम्तिहान किया जा रहा है और इसमें शक नहीं कि तम्हारा परवरदिगार (बस खुदाए रहमान है) तो तुम मेरी पैरवी करो और मेरा कहा मानो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,91,'Taa-Haa','قَالُواْ لَن نَّبۡرَحَ عَلَيۡهِ عَٰكِفِينَ حَتَّىٰ يَرۡجِعَ إِلَيۡنَا مُوسَىٰ','وہ کہنے لگے کہ جب تک موسیٰ ہمارے پاس واپس نہ آئیں ہم تو اس کی پوجا پر قائم رہیں گے','They replied, “We will not cease to worship it until Moses returns to us.”','तो वह लोग कहने लगे जब तक मूसा हमारे पास पलट कर न आएँ हम तो बराबर इसकी परसतिश पर डटे बैठे रहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,92,'Taa-Haa','قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذۡ رَأَيۡتَهُمۡ ضَلُّوٓاْ','(پھر موسیٰ نے ہارون سے) کہا کہ ہارون جب تم نے ان کو دیکھا تھا کہ گمراہ ہو رہے ہیں تو تم کو کس چیز نے روکا','Moses scolded ˹his brother˺, “O Aaron! What prevented you, when you saw them going astray','मूसा ने हारून की तरफ ख़िताब करके कहा ऐ हारून जब तुमने उनको देख लिया था गमुराह हो गए हैं तो तुम्हें मेरी पैरवी (क़ताल) करने को किसने मना किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,93,'Taa-Haa','أَلَّا تَتَّبِعَنِۖ أَفَعَصَيۡتَ أَمۡرِي','(یعنی) اس بات سے کہ تم میرے پیچھے چلے آؤ۔ بھلا تم نے میرے حکم کے خلاف (کیوں) کیا؟','from following after me? How could you disobey my orders?”','तो क्या तुमने मेरे हुक्म की नाफ़रमानी की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,94,'Taa-Haa','قَالَ يَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡيَتِي وَلَا بِرَأۡسِيٓۖ إِنِّي خَشِيتُ أَن تَقُولَ فَرَّقۡتَ بَيۡنَ بَنِيٓ إِسۡرَٰٓءِيلَ وَلَمۡ تَرۡقُبۡ قَوۡلِي','کہنے لگے کہ بھائی میری ڈاڑھی اور سر (کے بالوں) کو نہ پکڑیئے۔ میں تو اس سے ڈرا کہ آپ یہ نہ کہیں کہ تم نے بنی اسرائیل میں تفرقہ ڈال دیا اور میری بات کو ملحوظ نہ رکھا','Aaron pleaded, “O son of my mother! Do not seize me by my beard or ˹the hair of˺ my head. I really feared that you would say, ‘You have caused division among the Children of Israel, and did not observe my word.’”','हारून ने कहा ऐ मेरे माँजाए (भाई) मेरी दाढ़ी न पकडिऐ और न मेरे सर (के बाल) मैं तो उससे डरा कि (कहीं) आप (वापस आकर) ये (न) कहिए कि तुमने बनी इसराईल में फूट डाल दी और मेरी बात का भी ख्याल न रखा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,95,'Taa-Haa','قَالَ فَمَا خَطۡبُكَ يَٰسَٰمِرِيُّ','پھر (سامری سے) کہنے لگے کہ سامری تیرا کیا حال ہے؟','Moses then asked, “What did you think you were doing, O Sâmiri?”','तब सामरी से कहने लगे कि ओ सामरी तेरा क्या हाल है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,96,'Taa-Haa','قَالَ بَصُرۡتُ بِمَا لَمۡ يَبۡصُرُواْ بِهِۦ فَقَبَضۡتُ قَبۡضَةࣰ مِّنۡ أَثَرِ ٱلرَّسُولِ فَنَبَذۡتُهَا وَكَذَٰلِكَ سَوَّلَتۡ لِي نَفۡسِي','اس نے کہا کہ میں نے ایسی چیز دیکھی جو اوروں نے نہیں دیکھی تو میں نے فرشتے کے نقش پا سے (مٹی کی) ایک مٹھی بھر لی۔ پھر اس کو (بچھڑے کے قالب میں) ڈال دیا اور مجھے میرے جی نے (اس کام کو) اچھا بتایا','He said, “I saw what they did not see, so I took a handful ˹of dust˺ from the hoof-prints of ˹the horse of˺ the messenger-angel ˹Gabriel˺ then cast it ˹on the moulded calf˺. This is what my lower-self tempted me into.”','उसने (जवाब में) कहा मुझे वह चीज़ दिखाई दी जो औरों को न सूझी (जिबरील घोड़े पर सवार जा रहे थे) तो मैंने जिबरील फरिश्ते (के घोड़े) के निशाने क़दम की एक मुट्ठी (ख़ाक) की उठा ली फिर मैंने (बछड़ों के क़ालिब में) डाल दी (तो वह बोलेने लगा)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,97,'Taa-Haa','قَالَ فَٱذۡهَبۡ فَإِنَّ لَكَ فِي ٱلۡحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَۖ وَإِنَّ لَكَ مَوۡعِدࣰ ا لَّن تُخۡلَفَهُۥۖ وَٱنظُرۡ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِي ظَلۡتَ عَلَيۡهِ عَاكِفࣰ اۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِي ٱلۡيَمِّ نَسۡفًا','(موسیٰ نے) کہا جا تجھ کو دنیا کی زندگی میں یہ (سزا) ہے کہ کہتا رہے کہ مجھ کو ہاتھ نہ لگانا اور تیرے لئے ایک اور وعدہ ہے (یعنی عذاب کا) جو تجھ سے ٹل نہ سکے گا اور جس معبود (کی پوجا) پر تو (قائم و) معتکف تھا اس کو دیکھ۔ ہم اسے جلادیں گے پھر اس (کی راکھ) کو اُڑا کر دریا میں بکھیر دیں گے','Moses said, “Go away then! And for ˹the rest of your˺ life you will surely be crying, ‘Do not touch ˹me˺!’ Then you will certainly have a fate that you cannot escape. Now look at your god to which you have been devoted: we will burn it up, then scatter it in the sea completely.”','और उस वक्त मुझे मेरे नफ्स ने यही सुझाया मूसा ने कहा चल (दूर हो) तेरे लिए (इस दुनिया की) ज़िन्दगी में तो (ये सज़ा है) तू कहता फ़िरेगा कि मुझे न छूना (वरना बुख़ार चढ़ जाएगा) और (आख़िरत में भी) यक़ीनी तेरे लिए (अज़ाब का) वायदा है कि हरगिज़ तुझसे ख़िलाफ़ न किया जाएगा और तू अपने माबूद को तो देख जिस (की इबादत) पर तू डट बैठा था कि हम उसे यक़ीनन जलाकर (राख) कर डालेंगे फिर हम उसे तितिर बितिर करके दरिया में उड़ा देगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,98,'Taa-Haa','إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۚ وَسِعَ كُلَّ شَيۡءٍ عِلۡمࣰ ا','تمہارا معبود خدا ہی ہے جس کے سوا کوئی معبود نہیں۔ اس کا علم ہر چیز پر محیط ہے','˹Then Moses addressed his people,˺ “Your only god is Allah, there is no god ˹worthy of worship˺ except Him. He encompasses everything in ˹His˺ knowledge.”','तुम्हारा माबूद तो बस वही ख़ुदा है जिसके सिवा कोई और माबूद बरहक़ नहीं कि उसका इल्म हर चीज़ पर छा गया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,99,'Taa-Haa','كَذَٰلِكَ نَقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ مَا قَدۡ سَبَقَۚ وَقَدۡ ءَاتَيۡنَٰكَ مِن لَّدُنَّا ذِكۡرࣰ ا','اس طرح پر ہم تم سے وہ حالات بیان کرتے ہیں جو گذر چکے ہیں۔ اور ہم نے تمہیں اپنے پاس سے نصیحت (کی کتاب) عطا فرمائی ہے','This is how We relate to you ˹O Prophet˺ some of the stories of the past. And We have certainly granted you a Reminder from Us','(ऐ रसूल) हम तुम्हारे सामने यूँ वाक़ेयात बयान करते हैं जो गुज़र चुके और हमने ही तुम्हारे पास अपनी बारगाह से कुरान अता किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,100,'Taa-Haa','مَّنۡ أَعۡرَضَ عَنۡهُ فَإِنَّهُۥ يَحۡمِلُ يَوۡمَ ٱلۡقِيَٰمَةِ وِزۡرًا','جو شخص اس سے منہ پھیرے گا وہ قیامت کے دن (گناہ کا) بوجھ اُٹھائے گا','Whoever turns away from it will surely bear the burden ˹of sin˺ on the Day of Judgment','जिसने उससे मुँह फेरा वह क़यामत के दिन यक़ीनन (अपने बुरे आमाल का) बोझ उठाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,101,'Taa-Haa','خَٰلِدِينَ فِيهِۖ وَسَآءَ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ حِمۡلࣰ ا','(ایسے لوگ) ہمیشہ اس (عذاب) میں (مبتلا) رہیں گے اور یہ بوجھ قیامت کے روز ان کے لئے برا ہے','suffering its consequences forever. What an evil burden they will carry on Judgment Day','और उसी हाल में हमेशा रहेंगे और क्या ही बुरा बोझ है क़यामत के दिन ये लोग उठाए होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,102,'Taa-Haa','يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ وَنَحۡشُرُ ٱلۡمُجۡرِمِينَ يَوۡمَئِذࣲ زُرۡقࣰ ا','جس روز صور پھونکا جائے گا اور ہم گنہگاروں کو اکھٹا کریں گے اور ان کی آنکھیں نیلی نیلی ہوں گی','˹Beware of˺ the Day the Trumpet will be blown, and We will gather the wicked on that Day blue-faced ˹from horror and thirst˺','जिस दिन सूर फूँका जाएगा और हम उस दिन गुनाहगारों को (उनकी) ऑंखें पुतली (अन्धी) करके (आमने-सामने) जमा करेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,103,'Taa-Haa','يَتَخَٰفَتُونَ بَيۡنَهُمۡ إِن لَّبِثۡتُمۡ إِلَّا عَشۡرࣰ ا','(تو) وہ آپس میں آہستہ آہستہ کہیں گے کہ تم (دنیا میں) صرف دس ہی دن رہے ہو','They will whisper among themselves, “You stayed no more than ten days ˹on the earth˺.”','(और) आपस में चुपके-चुपके कहते होंगे कि (दुनिया या क़ब्र में) हम लोग (बहुत से बहुत) नौ दस दिन ठहरे होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,104,'Taa-Haa','نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَ إِذۡ يَقُولُ أَمۡثَلُهُمۡ طَرِيقَةً إِن لَّبِثۡتُمۡ إِلَّا يَوۡمࣰ ا','جو باتیں یہ کریں گے ہم خوب جانتے ہیں۔ اس وقت ان میں سب سے اچھی راہ والا (یعنی عاقل وہوشمند) کہے گا کہ (نہیں بلکہ) صرف ایک ہی روز ٹھہرے ہو','We know best what they will say—the most reasonable of them will say, “You stayed no more than a day.”','जो कुछ ये लोग (उस दिन) कहेंगे हम खूब जानते हैं कि जो इनमें सबसे ज्यादा होशियार होगा बोल उठेगा कि तुम बस (बहुत से बहुत) एक दिन ठहरे होगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,105,'Taa-Haa','وَيَسۡـَٔلُونَكَ عَنِ ٱلۡجِبَالِ فَقُلۡ يَنسِفُهَا رَبِّي نَسۡفࣰ ا','اور تم سے پہاڑوں کے بارے میں دریافت کرتے ہیں۔ کہہ دو کہ خدا ان کو اُڑا کر بکھیر دے گا','And ˹if˺ they ask you ˹O Prophet˺ about the mountains, ˹then˺ say, “My Lord will wipe them out completely','(और ऐ रसूल) तुम से लोग पहाड़ों के बारे में पूछा करते हैं (कि क़यामत के रोज़ क्या होगा)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,106,'Taa-Haa','فَيَذَرُهَا قَاعࣰ ا صَفۡصَفࣰ ا','اور زمین کو ہموار میدان کر چھوڑے گا','leaving the earth level and bare','तो तुम कह दो कि मेरा परवरदिगार बिल्कुल रेज़ा रेज़ा करके उड़ा डालेगा और ज़मीन को एक चटियल मैदान कर छोड़ेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,107,'Taa-Haa','لَّا تَرَىٰ فِيهَا عِوَجࣰ ا وَلَآ أَمۡتࣰ ا','جس میں نہ تم کجی (اور پستی) دیکھو گے نہ ٹیلا (اور بلندی)','with neither depressions nor elevations to be seen.”','कि (ऐ शख्स) न तो उसमें मोड़ देखेगा और न ऊँच-नीच');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,108,'Taa-Haa','يَوۡمَئِذࣲ يَتَّبِعُونَ ٱلدَّاعِيَ لَا عِوَجَ لَهُۥۖ وَخَشَعَتِ ٱلۡأَصۡوَاتُ لِلرَّحۡمَٰنِ فَلَا تَسۡمَعُ إِلَّا هَمۡسࣰ ا','اس روز لوگ ایک پکارنے والے کے پیچھے چلیں گے اور اس کی پیروی سے انحراف نہ کرسکیں گے اور خدا کے سامنے آوازیں پست ہوجائیں گی تو تم آواز خفی کے سوا کوئی آواز نہ سنو گے','On that Day all will follow the caller ˹for assembly˺, ˹and˺ none will dare to deviate. All voices will be hushed before the Most Compassionate. Only whispers will be heard','उस दिन लोग एक पुकारने वाले इसराफ़ील की आवाज़ के पीछे (इस तरह सीधे) दौड़ पड़ेगे कि उसमें कुछ भी कज़ी न होगी और आवाज़े उस दिन खुदा के सामने (इस तरह) घिघियाएगें कि तू घुनघुनाहट के सिवा और कुछ न सुनेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,109,'Taa-Haa','يَوۡمَئِذࣲ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَرَضِيَ لَهُۥ قَوۡلࣰ ا','اس روز (کسی کی) سفارش کچھ فائدہ نہ دے گی مگر اس شخص کی جسے خدا اجازت دے اور اس کی بات کو پسند فرمائے','On that Day no intercession will be of any benefit, except by those granted permission by the Most Compassionate and whose words are agreeable to Him','उस दिन किसी की सिफ़ारिश काम न आएगी मगर जिसको खुदा ने इजाज़त दी हो और उसका बोलना पसन्द करे जो कुछ उन लोगों के सामने है और जो कुछ उनके पीछे है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,110,'Taa-Haa','يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يُحِيطُونَ بِهِۦ عِلۡمࣰ ا','جو کچھ ان کے آگے ہے اور کچھ ان کے پیچھے ہے وہ اس کو جانتا ہے اور وہ (اپنے) علم سے خدا (کے علم) پر احاطہ نہیں کرسکتے','He ˹fully˺ knows what is ahead of them and what is behind them, but they cannot encompass Him in ˹their˺ knowledge','(ग़रज़ सब कुछ) वह जानता है और ये लोग अपने इल्म से उसपर हावी नहीं हो सकते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,111,'Taa-Haa','۞وَعَنَتِ ٱلۡوُجُوهُ لِلۡحَيِّ ٱلۡقَيُّومِۖ وَقَدۡ خَابَ مَنۡ حَمَلَ ظُلۡمࣰ ا','اور اس زندہ و قائم کے رو برو منہ نیچے ہوجائیں گے۔ اور جس نے ظلم کا بوجھ اٹھایا وہ نامراد رہا','And all faces will be humbled before the Ever-Living, All-Sustaining. And those burdened with wrongdoing will be in loss','और (क़यामत में) सारी (खुदाई के) का मुँह ज़िन्दा और बाक़ी रहने वाले खुदा के सामने झुक जाएँगे और जिसने जुल्म का बोझ (अपने सर पर) उठाया वह यक़ीनन नाकाम रहा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,112,'Taa-Haa','وَمَن يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤۡمِنࣱ فَلَا يَخَافُ ظُلۡمࣰ ا وَلَا هَضۡمࣰ ا','اور جو نیک کام کرے گا اور مومن بھی ہوگا تو اس کو نہ ظلم کا خوف ہوگا اور نہ نقصان کا','But whoever does good and is a believer will have no fear of being wronged or denied ˹their reward˺','और जिसने अच्छे-अच्छे काम किए और वह मोमिन भी है तो उसको न किसी तरह की बेइन्साफ़ी का डर है और न किसी नुक़सान का');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,113,'Taa-Haa','وَكَذَٰلِكَ أَنزَلۡنَٰهُ قُرۡءَانًا عَرَبِيࣰّ ا وَصَرَّفۡنَا فِيهِ مِنَ ٱلۡوَعِيدِ لَعَلَّهُمۡ يَتَّقُونَ أَوۡ يُحۡدِثُ لَهُمۡ ذِكۡرࣰ ا','اور ہم نے اس کو اسی طرح کا قرآن عربی نازل کیا ہے اور اس میں طرح طرح کے ڈراوے بیان کردیئے ہیں تاکہ لوگ پرہیزگار بنیں یا خدا ان کے لئے نصیحت پیدا کردے','And so We have sent it down as an Arabic Quran and varied the warnings in it, so perhaps they will shun evil or it may cause them to be mindful','हमने उसको उसी तरह अरबी ज़बान का कुरान नाज़िल फ़रमाया और उसमें अज़ाब के तरह-तरह के वायदे बयान किए ताकि ये लोग परहेज़गार बनें या उनके मिजाज़ में इबरत पैदा कर दे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,114,'Taa-Haa','فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۗ وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥۖ وَقُل رَّبِّ زِدۡنِي عِلۡمࣰ ا','تو خدا جو سچا بادشاہ ہے عالی قدر ہے۔ اور قرآن کی وحی جو تمہاری طرف بھیجی جاتی ہے اس کے پورا ہونے سے پہلے قرآن کے (پڑھنے کے) لئے جلدی نہ کیا کرو اور دعا کرو کہ میرے پروردگار مجھے اور زیادہ علم دے','Exalted is Allah, the True King! Do not rush to recite ˹a revelation of˺ the Quran ˹O Prophet˺ before it is ˹properly˺ conveyed to you, and pray, “My Lord! Increase me in knowledge.”','पस (दो जहाँ का) सच्चा बादशाह खुदा बरतर व आला है और (ऐ रसूल) कुरान के (पढ़ने) में उससे पहले कि तुम पर उसकी ''''वही'''' पूरी कर दी जाए जल्दी न करो और दुआ करो कि ऐ मेरे पालने वाले मेरे इल्म को और ज्यादा फ़रमा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,115,'Taa-Haa','وَلَقَدۡ عَهِدۡنَآ إِلَىٰٓ ءَادَمَ مِن قَبۡلُ فَنَسِيَ وَلَمۡ نَجِدۡ لَهُۥ عَزۡمࣰ ا','اور ہم نے پہلے آدم سے عہد لیا تھا مگر وہ (اسے) بھول گئے اور ہم نے ان میں صبر وثبات نہ دیکھا','And indeed, We once made a covenant with Adam, but he forgot, and ˹so˺ We did not find determination in him','और हमने आदम से पहले ही एहद ले लिया था कि उस दरख्त के पास न जाना तो आदम ने उसे तर्क कर दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,116,'Taa-Haa','وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ','اور جب ہم نے فرشتوں سے کہا کہ آدم کے آگے سجدہ کرو تو سب سجدے میں گر پڑے مگر ابلیس نے انکار کیا','And ˹remember˺ when We said to the angels, “Prostrate before Adam,” so they all did—but not Iblîs, who refused ˹arrogantly˺','और हमने उनमें साबित व इस्तक़लाल न पाया और जब हमने फ़रिश्तों से कहा कि आदम को सजदा करो तो सबने सजदा किया मगर शैतान ने इन्कार किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,117,'Taa-Haa','فَقُلۡنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوࣱّ لَّكَ وَلِزَوۡجِكَ فَلَا يُخۡرِجَنَّكُمَا مِنَ ٱلۡجَنَّةِ فَتَشۡقَىٰٓ','ہم نے فرمایا کہ آدم یہ تمہارا اور تمہاری بیوی کا دشمن ہے تو یہ کہیں تم دونوں کو بہشت سے نکلوا نہ دے۔ پھر تم تکلیف میں پڑجاؤ','So We cautioned, “O Adam! This is surely an enemy to you and to your wife. So do not let him drive you both out of Paradise, for you ˹O Adam˺ would then suffer ˹hardship˺','तो मैंने (आदम से कहा) कि ऐ आदम ये यक़ीनी तुम्हारा और तुम्हारी बीवी का दुशमन है तो कहीं तुम दोनों को बेहिश्त से निकलवा न छोड़े तो तुम (दुनिया की) मुसीबत में फँस जाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,118,'Taa-Haa','إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعۡرَىٰ','یہاں تم کو یہ (آسائش) ہوگی کہ نہ بھوکے رہو نہ ننگے','Here it is guaranteed that you will never go hungry or unclothed','कुछ शक नहीं कि (बेहिश्त में) तुम्हें ये आराम है कि न तो तुम यहाँ भूके रहोगे और न नँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,119,'Taa-Haa','وَأَنَّكَ لَا تَظۡمَؤُاْ فِيهَا وَلَا تَضۡحَىٰ','اور یہ کہ نہ پیاسے رہو اور نہ دھوپ کھاؤ','nor will you ˹ever˺ suffer from thirst or ˹the sun’s˺ heat.”','और न यहाँ प्यासे रहोगे और न धूप खाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,120,'Taa-Haa','فَوَسۡوَسَ إِلَيۡهِ ٱلشَّيۡطَٰنُ قَالَ يَٰٓـَٔادَمُ هَلۡ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلۡخُلۡدِ وَمُلۡكࣲ لَّا يَبۡلَىٰ','تو شیطان نے ان کے دل میں وسوسہ ڈالا۔ (اور) کہا کہ آدم بھلا میں تم کو (ایسا) درخت بتاؤں (جو) ہمیشہ کی زندگی کا (ثمرہ دے) اور (ایسی) بادشاہت کہ کبھی زائل نہ ہو','But Satan whispered to him, saying, “O Adam! Shall I show you the Tree of Immortality and a kingdom that does not fade away?”','तो शैतान ने उनके दिल में वसवसा डाला (और) कहा ऐ आदम क्या मैं तम्हें (हमेशगी की ज़िन्दगी) का दरख्त और वह सल्तनत जो कभी ज़ाएल न हो बता दूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,121,'Taa-Haa','فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ','تو دونوں نے اس درخت کا پھل کھا لیا تو ان پر ان کی شرمگاہیں ظاہر ہوگئیں اور وہ اپنے (بدنوں) پر بہشت کے پتّے چپکانے لگے۔ اور آدم نے اپنے پروردگار کے حکم خلاف کیا تو (وہ اپنے مطلوب سے) بےراہ ہو گئے','So they both ate from the tree and then their nakedness was exposed to them, prompting them to cover themselves with leaves from Paradise. So Adam disobeyed his Lord, and ˹so˺ lost his way','चुनान्चे दोनों मियाँ बीबी ने उसी में से कुछ खाया तो उनका आगा पीछा उनपर ज़ाहिर हो गया और दोनों बेहिश्त के (दरख्त के) पत्ते अपने आगे पीछे पर चिपकाने लगे और आदम ने अपने परवरदिगार की नाफ़रमानी की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,122,'Taa-Haa','ثُمَّ ٱجۡتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيۡهِ وَهَدَىٰ','پھر ان کے پروردگار نے ان کو نوازا تو ان پر مہربانی سے توجہ فرمائی اور سیدھی راہ بتائی','Then his Lord chose him ˹for His grace˺, accepted his repentance, and guided him ˹rightly˺','तो (राहे सवाब से) बेराह हो गए इसके बाद उनके परवरदिगार ने बर गुज़ीदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,123,'Taa-Haa','قَالَ ٱهۡبِطَا مِنۡهَا جَمِيعَۢاۖ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوࣱّۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدࣰ ى فَمَنِ ٱتَّبَعَ هُدَايَ فَلَا يَضِلُّ وَلَا يَشۡقَىٰ','فرمایا کہ تم دونوں یہاں سے نیچے اتر جاؤ۔ تم میں بعض بعض کے دشمن (ہوں گے) پھر اگر میری طرف سے تمہارے پاس ہدایت آئے تو جو شخص میری ہدایت کی پیروی کرے گا وہ نہ گمراہ ہوگا اور نہ تکلیف میں پڑے گا','Allah said, “Descend, both of you, from here together ˹with Satan˺ as enemies to each other. Then when guidance comes to you from Me, whoever follows My guidance will neither go astray ˹in this life˺ nor suffer ˹in the next˺','फिर उनकी तौबा कुबूल की और उनकी हिदायत की फरमाया कि तुम दोनों बेहश्त से नीचे उतर जाओ तुम में से एक का एक दुशमन है फिर अगर तुम्हारे पास मेरी तरफ से हिदायत पहुँचे तो (तुम) उसकी पैरवी करना क्योंकि जो शख्स मेरी हिदायत पर चलेगा न तो गुमराह होगा और न मुसीबत में फँसेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,124,'Taa-Haa','وَمَنۡ أَعۡرَضَ عَن ذِكۡرِي فَإِنَّ لَهُۥ مَعِيشَةࣰ ضَنكࣰ ا وَنَحۡشُرُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ أَعۡمَىٰ','اور جو میری نصیحت سے منہ پھیرے گا اس کی زندگی تنگ ہوجائے گی اور قیامت کو ہم اسے اندھا کرکے اٹھائیں گے','But whoever turns away from My Reminder will certainly have a miserable life, then We will raise them up blind on the Day of Judgment.”','और जिस शख्स ने मेरी याद से मुँह फेरा तो उसकी ज़िन्दगी बहुत तंगी में बसर होगी और हम उसको क़यामत के दिन अंधा बना के उठाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,125,'Taa-Haa','قَالَ رَبِّ لِمَ حَشَرۡتَنِيٓ أَعۡمَىٰ وَقَدۡ كُنتُ بَصِيرࣰ ا','وہ کہے گا میرے پروردگار تو نے مجھے اندھا کرکے کیوں اٹھایا میں تو دیکھتا بھالتا تھا','They will cry, “My Lord! Why have you raised me up blind, although I used to see?”','वह कहेगा इलाही मैं तो (दुनिया में) ऑंख वाला था तूने मुझे अन्धा करके क्यों उठाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,126,'Taa-Haa','قَالَ كَذَٰلِكَ أَتَتۡكَ ءَايَٰتُنَا فَنَسِيتَهَاۖ وَكَذَٰلِكَ ٱلۡيَوۡمَ تُنسَىٰ','خدا فرمائے گا کہ ایسا ہی (چاہیئے تھا) تیرے پاس میری آیتیں آئیں تو تونے ان کو بھلا دیا۔ اسی طرح آج ہم تجھ کو بھلا دیں گے','Allah will respond, “It is so, just as Our revelations came to you and you neglected them, so Today you are neglected.”','खुदा फरमाएगा ऐसा ही (होना चाहिए) हमारी आयतें भी तो तेरे पास आई तो तू उन्हें भुला बैठा और इसी तरह आज तू भी भूला दिया जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,127,'Taa-Haa','وَكَذَٰلِكَ نَجۡزِي مَنۡ أَسۡرَفَ وَلَمۡ يُؤۡمِنۢ بِـَٔايَٰتِ رَبِّهِۦۚ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَشَدُّ وَأَبۡقَىٰٓ','اور جو شخص حد سے نکل جائے اور اپنے پروردگار کی آیتوں پر ایمان نہ لائے ہم اس کو ایسا ہی بدلہ دیتے ہیں۔ اور آخرت کا عذاب بہت سخت اور بہت دیر رہنے والا ہے','This is how We reward whoever transgresses and does not believe in the revelations of their Lord. And the punishment of the Hereafter is far more severe and more lasting','और जिसने (हद से) तजाविज़ किया और अपने परवरदिगार की आयतों पर ईमान न लाया उसको ऐसी ही बदला देगें और आख़िरत का अज़ाब तो यक़ीनी बहुत सख्त और बहुत देर पा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,128,'Taa-Haa','أَفَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّأُوْلِي ٱلنُّهَىٰ','کیا یہ بات ان لوگوں کے لئے موجب ہدایت نہ ہوئی کہ ہم ان سے پہلے بہت سے لوگوں کو ہلاک کرچکے ہیں جن کے رہنے کے مقامات میں یہ چلتے پھرتے ہیں۔ عقل والوں کے لئے اس میں (بہت سی) نشانیاں ہیں','Is it not yet clear to them how many peoples We destroyed before them, whose ruins they still pass by? Surely in this are signs for people of sound judgment','तो क्या उन (अहले मक्का) को उस (खुदा) ने ये नहीं बता दिया था कि हमने उनके पहले कितने लोगों को हलाक कर डाला जिनके घरों में ये लोग चलते फिरते हैं इसमें शक नहीं कि उसमें अक्लमंदों के लिए (कुदरते खुदा की) यक़ीनी बहुत सी निशानियाँ हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,129,'Taa-Haa','وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ لَكَانَ لِزَامࣰ ا وَأَجَلࣱ مُّسَمࣰّ ى','اور اگر ایک بات تمہارے پروردگار کی طرف سے پہلے صادر اور (جزائے اعمال کے لئے) ایک میعاد مقرر نہ ہوچکی ہوتی تو (نزول) عذاب لازم ہوجاتا','Had it not been for a prior decree from your Lord ˹O Prophet˺ and a term already set, their ˹instant˺ doom would have been inevitable','और (ऐ रसूल) अगर तुम्हारे परवरदिगार की तरफ से पहले ही एक वायदा और अज़ाब का) एक वक्त मुअय्युन न होता तो (उनकी हरकतों से) फ़ौरन अज़ाब का आना लाज़मी बात थी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,130,'Taa-Haa','فَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ غُرُوبِهَاۖ وَمِنۡ ءَانَآيِٕ ٱلَّيۡلِ فَسَبِّحۡ وَأَطۡرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرۡضَىٰ','پس جو کچھ یہ بکواس کرتے ہیں اس پر صبر کرو۔ اور سورج کے نکلنے سے پہلے اور اس کے غروب ہونے سے پہلے اپنے پروردگار کی تسبیح وتحمید کیا کرو۔ اور رات کی ساعات (اولین) میں بھی اس کی تسبیح کیا کرو اور دن کی اطراف (یعنی دوپہر کے قریب ظہر کے وقت بھی) تاکہ تم خوش ہوجاؤ','So be patient ˹O Prophet˺ with what they say. And glorify the praises of your Lord before sunrise and before sunset, and glorify Him in the hours of the night and at both ends of the day, so that you may be pleased ˹with the reward˺','(ऐ रसूल) जो कुछ ये कुफ्फ़ार बका करते हैं तुम उस पर सब्र करो और आफ़ताब निकलने के क़ब्ल और उसके ग़ुरूब होने के क़ब्ल अपने परवरदिगार की हम्दोसना के साथ तसबीह किया करो और कुछ रात के वक़्तों में और दिन के किनारों में तस्बीह करो ताकि तुम निहाल हो जाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,131,'Taa-Haa','وَلَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجࣰ ا مِّنۡهُمۡ زَهۡرَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا لِنَفۡتِنَهُمۡ فِيهِۚ وَرِزۡقُ رَبِّكَ خَيۡرࣱ وَأَبۡقَىٰ','اور کئی طرح کے لوگوں کو جو ہم نے دنیا کی زندگی میں آرائش کی چیزوں سے بہرہ مند کیا ہے تاکہ ان کی آزمائش کریں ان پر نگاہ نہ کرنا۔ اور تمہاری پروردگار کی (عطا فرمائی ہوئی) روزی بہت بہتر اور باقی رہنے والی ہے','Do not let your eyes crave what We have allowed some of the disbelievers to enjoy; the ˹fleeting˺ splendour of this worldly life, which We test them with. But your Lord’s provision ˹in the Hereafter˺ is far better and more lasting','और (ऐ रसूल) जो उनमें से कुछ लोगों को दुनिया की इस ज़रा सी ज़िन्दगी की रौनक़ से निहाल कर दिया है ताकि हम उनको उसमें आज़माएँ तुम अपनी नज़रें उधर न बढ़ाओ और (इससे) तुम्हारे परवरदिगार की रोज़ी (सवाब) कहीं बेहतर और ज्यादा पाएदार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,132,'Taa-Haa','وَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَيۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقࣰ اۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَٰقِبَةُ لِلتَّقۡوَىٰ','اور اپنے گھر والوں کو نماز کا حکم کرو اور اس پر قائم رہو۔ ہم تم سے روزی کے خواستگار نہیں۔ بلکہ تمہیں ہم روزی دیتے ہیں اور (نیک) انجام (اہل) تقویٰ کا ہے','Bid your people to pray, and be diligent in ˹observing˺ it. We do not ask you to provide. It is We Who provide for you. And the ultimate outcome is ˹only˺ for ˹the people of˺ righteousness','और अपने घर वालों को नमाज़ का हुक्म दो और तुम खुद भी उसके पाबन्द रहो हम तुम से रोज़ी तो तलब करते नहीं (बल्कि) हम तो खुद तुमको रोज़ी देते हैं और परहेज़गारी ही का तो अन्जाम बखैर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,133,'Taa-Haa','وَقَالُواْ لَوۡلَا يَأۡتِينَا بِـَٔايَةࣲ مِّن رَّبِّهِۦٓۚ أَوَلَمۡ تَأۡتِهِم بَيِّنَةُ مَا فِي ٱلصُّحُفِ ٱلۡأُولَىٰ','اور کہتے ہیں کہ یہ (پیغمبر) اپنے پروردگار کی طرف سے ہمارے پاس کوئی نشانی کیوں نہیں لاتے۔ کیا ان کے پاس پہلی کتابوں کی نشانی نہیں آئی؟','They demand, “If only he could bring us a sign from his Lord!” Have they not ˹already˺ received a confirmation of what is in earlier Scriptures','और (अहले मक्का) कहते हैं कि अपने परवरदिगार की तरफ से हमारे पास कोई मौजिज़ा हमारी मर्ज़ी के मुवाफिक़ क्यों नहीं लाते तो क्या जो (पेशीव गोइयाँ) अगली किताबों (तौरेत, इन्जील) में (इसकी) गवाह हैं वह भी उनके पास नहीं पहुँची');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,134,'Taa-Haa','وَلَوۡ أَنَّآ أَهۡلَكۡنَٰهُم بِعَذَابࣲ مِّن قَبۡلِهِۦ لَقَالُواْ رَبَّنَا لَوۡلَآ أَرۡسَلۡتَ إِلَيۡنَا رَسُولࣰ ا فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبۡلِ أَن نَّذِلَّ وَنَخۡزَىٰ','اور اگر ہم ان کو پیغمبر (کے بھیجنے) سے پیشتر کسی عذاب سے ہلاک کردیتے تو وہ کہتے کہ اے ہمارے پروردگار تو نے ہماری طرف کوئی پیغمبر کیوں نہ بھیجا کہ ہم ذلیل اور رسوا ہونے سے پہلے تیرے کلام (واحکام) کی پیروی کرتے','Had We destroyed them with a torment before this ˹Prophet came˺, they would have surely argued, “Our Lord! If only You had sent us a messenger, we would have followed Your revelations before being humiliated and put to shame.”','और अगर हम उनको इस रसूल से पहले अज़ाब से हलाक कर डालते तो ज़रूर कहते कि ऐ हमारे पालने वाले तूने हमारे पास (अपना) रसूल क्यों न भेजा तो हम अपने ज़लील व रूसवा होने से पहले तेरी आयतों की पैरवी ज़रूर करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (20,135,'Taa-Haa','قُلۡ كُلࣱّ مُّتَرَبِّصࣱ فَتَرَبَّصُواْۖ فَسَتَعۡلَمُونَ مَنۡ أَصۡحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِيِّ وَمَنِ ٱهۡتَدَىٰ','کہہ دو کہ سب (نتائج اعمال) کے منتظر ہیں سو تم بھی منتظر رہو۔ عنقریب تم کو معلوم ہوجائے گا کہ (دین کے) سیدھے رستے پر چلنے والے کون ہیں اور (جنت کی طرف) راہ پانے والے کون ہیں (ہم یا تم)','Say ˹to them, O Prophet˺, “Each ˹of us˺ is waiting, so keep waiting! You will soon know who is on the Straight Path and is ˹rightly˺ guided.”','रसूल तुम कह दो कि हर शख्स (अपने अन्जामकार का) मुन्तिज़र है तो तुम भी इन्तिज़ार करो फिर तो तुम्हें बहुत जल्द मालूम हो जाएगा कि सीधी राह वाले कौन हैं (और कज़ी पर कौन हैं) हिदायत याफ़ता कौन है और गुमराह कौन है।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,1,'Al-Anbiyaa','ٱقۡتَرَبَ لِلنَّاسِ حِسَابُهُمۡ وَهُمۡ فِي غَفۡلَةࣲ مُّعۡرِضُونَ','لوگوں کا حساب (اعمال کا وقت) نزدیک آپہنچا ہے اور وہ غفلت میں (پڑے اس سے) منہ پھیر رہے ہیں','˹The time of˺ people’s judgment has drawn near, yet they are heedlessly turning away','लोगों के पास उनका हिसाब (उसका वक्त) अा पहुँचा और वह है कि गफ़लत में पड़े मुँह मोड़े ही जाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,2,'Al-Anbiyaa','مَا يَأۡتِيهِم مِّن ذِكۡرࣲ مِّن رَّبِّهِم مُّحۡدَثٍ إِلَّا ٱسۡتَمَعُوهُ وَهُمۡ يَلۡعَبُونَ','ان کے پاس کوئی نئی نصیحت ان کے پروردگار کی طرف سے نہیں آتی مگر وہ اسے کھیلتے ہوئے سنتے ہیں','Whatever new reminder comes to them from their Lord, they only listen to it jokingly','जब उनके परवरदिगार की तरफ से उनके पास कोई नया हुक्म आता है तो उसे सिर्फ कान लगाकर सुन लेते हैं और (फिर उसका) हँसी खेल उड़ाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,3,'Al-Anbiyaa','لَاهِيَةࣰ قُلُوبُهُمۡۗ وَأَسَرُّواْ ٱلنَّجۡوَى ٱلَّذِينَ ظَلَمُواْ هَلۡ هَٰذَآ إِلَّا بَشَرࣱ مِّثۡلُكُمۡۖ أَفَتَأۡتُونَ ٱلسِّحۡرَ وَأَنتُمۡ تُبۡصِرُونَ','ان کے دل غفلت میں پڑے ہوئے ہیں اور ظالم لوگ (آپس میں) چپکے چپکے باتیں کرتے ہیں کہ یہ (شخص کچھ بھی) نہیں مگر تمہارے جیسا آدمی ہے۔ تو تم آنکھوں دیکھتے جادو (کی لپیٹ) میں کیوں آتے ہو','with their hearts ˹totally˺ distracted. The evildoers would converse secretly, ˹saying,˺ “Is this ˹one˺ not human like yourselves? Would you fall for ˹this˺ witchcraft, even though you can ˹clearly˺ see?”','उनके दिल (आख़िरत के ख्याल से) बिल्कुल बेख़बर हैं और ये ज़ालिम चुपके-चुपके कानाफूसी किया करते हैं कि ये शख्स (मोहम्मद कुछ भी नहीं) बस तुम्हारे ही सा आदमी है तो क्या तुम दीन व दानिस्ता जादू में फँसते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,4,'Al-Anbiyaa','قَالَ رَبِّي يَعۡلَمُ ٱلۡقَوۡلَ فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ','(پیغمبر نے) کہا کہ جو بات آسمان اور زمین میں (کہی جاتی) ہے میرا پروردگار اسے جانتا ہے۔ اور وہ سننے والا (اور) جاننے والا ہے','The Prophet responded, “My Lord ˹fully˺ knows every word spoken in the heavens and the earth. For He is the All-Hearing, All-Knowing.”','(तो उस पर) रसूल ने कहा कि मेरा परवरदिगार जितनी बातें आसमान और ज़मीन में होती हैं खूब जानता है (फिर क्यों कानाफूसी करते हो) और वह तो बड़ा सुनने वाला वाक़िफ़कार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,5,'Al-Anbiyaa','بَلۡ قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمِۭ بَلِ ٱفۡتَرَىٰهُ بَلۡ هُوَ شَاعِرࣱ فَلۡيَأۡتِنَا بِـَٔايَةࣲ كَمَآ أُرۡسِلَ ٱلۡأَوَّلُونَ','بلکہ (ظالم) کہنے لگے کہ (یہ قرآن) پریشان (باتیں ہیں جو) خواب (میں دیکھ لی) ہیں۔ (نہیں) بلکہ اس نے اس کو اپنی طرف سے بنا لیا ہے (نہیں) بلکہ (یہ شعر ہے جو اس) شاعر (کا نتیجہٴ طبع) ہے۔ تو جیسے پہلے (پیغمبر نشانیاں دے کر) بھیجے گئے تھے (اسی طرح) یہ بھی ہمارے پاس کوئی نشانی لائے','Yet they say, “This ˹Quran˺ is a set of confused dreams! No, he has fabricated it! No, he must be a poet! So let him bring us a ˹tangible˺ sign like those ˹prophets˺ sent before.”','(उस पर भी उन लोगों ने इक्तिफ़ा न की) बल्कि कहने लगे (ये कुरान तो) ख़ाबहाय परीशाँ का मजमूआ है बल्कि उसने खुद अपने जी से झूट-मूट गढ़ लिया है बल्कि ये शख्स शायर है और अगर हक़ीकतन रसूल है) तो जिस तरह अगले पैग़म्बर मौजिज़ों के साथ भेजे गए थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,6,'Al-Anbiyaa','مَآ ءَامَنَتۡ قَبۡلَهُم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَآۖ أَفَهُمۡ يُؤۡمِنُونَ','ان سے پہلے جن بستیوں کو ہم نے ہلاک کیا وہ ایمان نہیں لاتی تھیں۔ تو کیا یہ ایمان لے آئیں گے','Not a ˹single˺ society We destroyed before them ever believed ˹after receiving the signs˺. Will these ˹pagans˺ then believe','उसी तरह ये भी कोई मौजिज़ा (जैसा हम कहें) हमारे पास भला लाए तो सही इनसे पहले जिन बस्तियों को तबाह कर डाला (मौजिज़े भी देखकर तो) ईमान न लाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,7,'Al-Anbiyaa','وَمَآ أَرۡسَلۡنَا قَبۡلَكَ إِلَّا رِجَالࣰ ا نُّوحِيٓ إِلَيۡهِمۡۖ فَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ','اور ہم نے تم سے پہلے مرد ہی (پیغمبر بنا کر) بھیجے جن کی طرف ہم وحی بھیجتے تھے۔ اگر تم نہیں جانتے تو جو یاد رکھتے ہیں ان سے پوچھ لو','We did not send ˹messengers˺ before you ˹O Prophet˺ except mere men inspired by Us. If you ˹polytheists˺ do not know ˹this already˺, then ask those who have knowledge ˹of the Scriptures˺','तो क्या ये लोग ईमान लाएँगे और ऐ रसूल हमने तुमसे पहले भी आदमियों ही को (रसूल बनाकर) भेजा था कि उनके पास ''''वही'''' भेजा करते थे तो अगर तुम लोग खुद नहीं जानते हो तो आलिमों से पूँछकर देखो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,8,'Al-Anbiyaa','وَمَا جَعَلۡنَٰهُمۡ جَسَدࣰ ا لَّا يَأۡكُلُونَ ٱلطَّعَامَ وَمَا كَانُواْ خَٰلِدِينَ','اور ہم نے ان کے لئے ایسے جسم نہیں بنائے تھے کہ کھانا نہ کھائیں اور نہ وہ ہمیشہ رہنے والے تھے','We did not give those messengers ˹supernatural˺ bodies that did not need food, nor were they immortal','और हमने उन (पैग़म्बरों) के बदन ऐसे नहीं बनाए थे कि वह खाना न खाएँ और न वह (दुनिया में) हमेशा रहने सहने वाले थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,9,'Al-Anbiyaa','ثُمَّ صَدَقۡنَٰهُمُ ٱلۡوَعۡدَ فَأَنجَيۡنَٰهُمۡ وَمَن نَّشَآءُ وَأَهۡلَكۡنَا ٱلۡمُسۡرِفِينَ','پھر ہم نے ان کے بارے میں (اپنا) وعدہ سچا کردیا تو ان کو اور جس کو چاہا نجات دی اور حد سے نکل جانے والوں کو ہلاک کردیا','Then We fulfilled Our promise to them, saving them along with whoever We willed and destroying the transgressors','फिर हमने उन्हें (अपना अज़ाब का) वायदा सच्चा कर दिखाया (और जब अज़ाब आ पहुँचा) तो हमने उन पैग़म्बरों को और जिस जिसको चाहा छुटकारा दिया और हद से बढ़ जाने वालों को हलाक कर डाला');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,10,'Al-Anbiyaa','لَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ كِتَٰبࣰ ا فِيهِ ذِكۡرُكُمۡۚ أَفَلَا تَعۡقِلُونَ','ہم نے تمہاری طرف ایسی کتاب نازل کی ہے جس میں تمہارا تذکرہ ہے۔ کیا تم نہیں سمجھتے','We have surely revealed to you a Book, in which there is glory for you. Will you not then understand','हमने तो तुम लोगों के पास वह किताब (कुरान) नाज़िल की है जिसमें तुम्हारा (भी) ज़िक्रे (ख़ैर) है तो क्या तुम लोग (इतना भी) समझते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,11,'Al-Anbiyaa','وَكَمۡ قَصَمۡنَا مِن قَرۡيَةࣲ كَانَتۡ ظَالِمَةࣰ وَأَنشَأۡنَا بَعۡدَهَا قَوۡمًا ءَاخَرِينَ','اور ہم نے بہت سی بستیوں کو جو ستمگار تھیں ہلاک کر مارا اور ان کے بعد اور لوگ پیدا کردیئے','˹Imagine˺ how many societies of wrongdoers We have destroyed, raising up other people after them','और हमने कितनी बस्तियों को जिनके रहने वाले सरकश थे बरबाद कर दिया और उनके बाद दूसरे लोगों को पैदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,12,'Al-Anbiyaa','فَلَمَّآ أَحَسُّواْ بَأۡسَنَآ إِذَا هُم مِّنۡهَا يَرۡكُضُونَ','جب انہوں نے ہمارے (مقدمہ) عذاب کو دیکھا تو لگے اس سے بھاگنے','When the wrongdoers sensed ˹the arrival of˺ Our torment, they started to run away from their cities','तो जब उन लोगों ने हमारे अज़ाब की आहट पाई तो एका एकी भागने लगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,13,'Al-Anbiyaa','لَا تَرۡكُضُواْ وَٱرۡجِعُوٓاْ إِلَىٰ مَآ أُتۡرِفۡتُمۡ فِيهِ وَمَسَٰكِنِكُمۡ لَعَلَّكُمۡ تُسۡـَٔلُونَ','مت بھاگو اور جن (نعمتوں) میں تم عیش وآسائش کرتے تھے ان کی اور اپنے گھروں کی طرف لوٹ جاؤ۔ شاید تم سے (اس بارے میں) دریافت کیا جائے','˹They were told,˺ “Do not run away! Return to your luxuries and your homes, so you may be questioned ˹about your fate˺.”','(हमने कहा) भागो नहीं और उन्हीं बस्तियों और घरों में लौट जाओ जिनमें तुम चैन करते थे ताकि तुमसे कुछ पूछगछ की जाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,14,'Al-Anbiyaa','قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ','کہنے لگے ہائے شامت بےشک ہم ظالم تھے','They cried, “Woe to us! We have surely been wrongdoers.”','वह लोग कहने लगे हाए हमारी शामत बेशक हम सरकश तो ज़रूर थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,15,'Al-Anbiyaa','فَمَا زَالَت تِّلۡكَ دَعۡوَىٰهُمۡ حَتَّىٰ جَعَلۡنَٰهُمۡ حَصِيدًا خَٰمِدِينَ','تو وہ ہمیشہ اسی طرح پکارتے رہے یہاں تک کہ ہم نے ان کو (کھیتی کی طرح) کاٹ کر (اور آگ کی طرح) بجھا کر ڈھیر کردیا','They kept repeating their cry until We mowed them down, ˹leaving them˺ lifeless','ग़रज़ वह बराबर यही पड़े पुकारा किए यहाँ तक कि हमने उन्हें कटी हुई खेती की तरह बिछा के ठन्डा करके ढेर कर दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,16,'Al-Anbiyaa','وَمَا خَلَقۡنَا ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ','اور ہم نے آسمان اور زمین کو جو اور (مخلوقات) ان دونوں کے درمیان ہے اس کو لہوولعب کے لئے پیدا نہیں کیا','We did not create the heavens and the earth and everything in between for sport','और हमने आसमान और ज़मीन को और जो कुछ इन दोनों के दरमियान है बेकार लगो नहीं पैदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,17,'Al-Anbiyaa','لَوۡ أَرَدۡنَآ أَن نَّتَّخِذَ لَهۡوࣰ ا لَّٱتَّخَذۡنَٰهُ مِن لَّدُنَّآ إِن كُنَّا فَٰعِلِينَ','اگر ہم چاہتے کہ کھیل (کی چیزیں یعنی زن وفرزند) بنائیں تو اگر ہم کو کرنا ہوتا تو ہم اپنے پاس سے بنالیتے','Had We intended to take ˹some˺ amusement, We could have found it in Our presence, if that had been Our Will','अगर हम कोई खेल बनाना चाहते तो बेशक हम उसे अपनी तजवीज़ से बना लेते अगर हमको करना होता (मगर हमें शायान ही न था)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,18,'Al-Anbiyaa','بَلۡ نَقۡذِفُ بِٱلۡحَقِّ عَلَى ٱلۡبَٰطِلِ فَيَدۡمَغُهُۥ فَإِذَا هُوَ زَاهِقࣱۚ وَلَكُمُ ٱلۡوَيۡلُ مِمَّا تَصِفُونَ','بلکہ ہم سچ کو جھوٹ پر کھینچ مارتے ہیں تو وہ اس کا سر توڑ دیتا ہے اور جھوٹ اسی وقت نابود ہوجاتا ہے۔ اور جو باتیں تم بناتے ہو ان سے تمہاری ہی خرابی ہے','In fact, We hurl the truth against falsehood, leaving it crushed, and it quickly vanishes. And woe be to you for what you claim','बल्कि हम तो हक़ को नाहक़ (के सर) पर खींच मारते हैं तो वह बिल्कुल के सर को कुचल देता है फिर वह उसी वक्त नेस्तवेनाबूद हो जाता है और तुम पर अफ़सोस है कि ऐसी-ऐसी नाहक़ बातें बनाये करते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,19,'Al-Anbiyaa','وَلَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَنۡ عِندَهُۥ لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَلَا يَسۡتَحۡسِرُونَ','اور جو لوگ آسمانوں میں اور جو زمین میں ہیں سب اسی کے (مملوک اور اُسی کا مال) ہیں۔ اور جو (فرشتے) اُس کے پاس ہیں وہ اس کی عبادت سے نہ کنیاتے ہیں اور نہ اکتاتے ہیں','To Him belong all those in the heavens and the earth. And those nearest to Him are not too proud to worship Him, nor do they tire','हालाँकि जो लोग (फरिश्ते) आसमान और ज़मीन में हैं (सब) उसी के (बन्दे) हैं और जो (फरिश्ते) उस सरकार में हैं न तो वह उसकी इबादत की शेख़ी करते हैं और न थकते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,20,'Al-Anbiyaa','يُسَبِّحُونَ ٱلَّيۡلَ وَٱلنَّهَارَ لَا يَفۡتُرُونَ','رات دن (اُس کی) تسبیح کرتے رہتے ہیں (نہ تھکتے ہیں) نہ اکتاتے ہیں','They glorify ˹Him˺ day and night, never wavering','रात और दिन उसकी तस्बीह किया करते हैं (और) कभी काहिली नहीं करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,21,'Al-Anbiyaa','أَمِ ٱتَّخَذُوٓاْ ءَالِهَةࣰ مِّنَ ٱلۡأَرۡضِ هُمۡ يُنشِرُونَ','بھلا لوگوں نے جو زمین کی چیزوں سے (بعض کو) معبود بنا لیا ہے (تو کیا) وہ ان کو (مرنے کے بعد) اُٹھا کھڑا کریں گے؟','Or have they taken gods from the earth, who can raise the dead','उन लोगों जो माबूद ज़मीन में बना रखे हैं क्या वही (लोगों को) ज़िन्दा करेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,22,'Al-Anbiyaa','لَوۡ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَاۚ فَسُبۡحَٰنَ ٱللَّهِ رَبِّ ٱلۡعَرۡشِ عَمَّا يَصِفُونَ','اگر آسمان اور زمین میں خدا کے سوا اور معبود ہوتے تو زمین وآسمان درہم برہم ہوجاتے۔ جو باتیں یہ لوگ بتاتے ہیں خدائے مالک عرش ان سے پاک ہے','Had there been other gods besides Allah in the heavens or the earth, both ˹realms˺ would have surely been corrupted. So Glorified is Allah, Lord of the Throne, far above what they claim','(अगर बफ़रने मुहाल) ज़मीन व आसमान में खुदा कि सिवा चन्द माबूद होते तो दोनों कब के बरबाद हो गए होते तो जो बातें ये लोग अपने जी से (उसके बारे में) बनाया करते हैं खुदा जो अर्श का मालिक है उन तमाम ऐबों से पाक व पाकीज़ा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,23,'Al-Anbiyaa','لَا يُسۡـَٔلُ عَمَّا يَفۡعَلُ وَهُمۡ يُسۡـَٔلُونَ','وہ جو کام کرتا ہے اس کی پرستش نہیں ہوگی اور (جو کام یہ لوگ کرتے ہیں اس کی) ان سے پرستش ہوگی','He cannot be questioned about what He does, but they will ˹all˺ be questioned','जो कुछ वह करता है उसकी पूछगछ नहीं हो सकती');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,24,'Al-Anbiyaa','أَمِ ٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةࣰۖ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡۖ هَٰذَا ذِكۡرُ مَن مَّعِيَ وَذِكۡرُ مَن قَبۡلِيۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٱلۡحَقَّۖ فَهُم مُّعۡرِضُونَ','کیا لوگوں نے خدا کو چھوڑ کر اور معبود بنالئے ہیں۔ کہہ دو کہ (اس بات پر) اپنی دلیل پیش کرو۔ یہ (میری اور) میرے ساتھ والوں کی کتاب بھی ہے اور جو مجھ سے پہلے (پیغمبر) ہوئے ہیں۔ ان کی کتابیں بھی ہیں۔ بلکہ (بات یہ ہے کہ) ان اکثر حق بات کو نہیں جانتے اور اس لئے اس سے منہ پھیر لیتے ہیں','Or have they taken other gods besides Him? Say, ˹O Prophet,˺ “Show ˹me˺ your proof. Here is ˹the Quran,˺ the Reminder for those with me; along with ˹earlier Scriptures,˺ the Reminder for those before me.” But most of them do not know the truth, so they turn away','(हाँ) और उन लोगों से बाज़पुर्स होगी क्या उन लोगों ने खुदा को छोड़कर कुछ और माबूद बना रखे हैं (ऐ रसूल) तुम कहो कि भला अपनी दलील तो पेश करो जो मेरे (ज़माने में) साथ है उनकी किताब (कुरान) और जो लोग मुझ से पहले थे उनकी किताबें (तौरेत वग़ैरह) ये (मौजूद) हैं (उनमें खुदा का शरीक बता दो) बल्कि उनमें से अक्सर तो हक़ (बात) को तो जानते ही नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,25,'Al-Anbiyaa','وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٍ إِلَّا نُوحِيٓ إِلَيۡهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدُونِ','اور جو پیغمبر ہم نےتم سے پہلے بھیجے ان کی طرف یہی وحی بھیجی کہ میرے سوا کوئی معبود نہیں تو میری ہی عبادت کرو','We never sent a messenger before you ˹O Prophet˺ without revealing to him: “There is no god ˹worthy of worship˺ except Me, so worship Me ˹alone˺.”','तो (जब हक़ का ज़िक्र आता है) ये लोग मुँह फेर लेते हैं और (ऐ रसूल) हमने तुमसे पहले जब कभी कोई रसूल भेजा तो उसके पास ''''वही'''' भेजते रहे कि बस हमारे सिवा कोई माबूद क़ाबिले परसतिश नहीं तो मेरी इबादत किया करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,26,'Al-Anbiyaa','وَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدࣰ اۗ سُبۡحَٰنَهُۥۚ بَلۡ عِبَادࣱ مُّكۡرَمُونَ','اور کہتے ہیں کہ خدا بیٹا رکھتا ہے۔ وہ پاک ہے (اس کے نہ بیٹا ہے نہ بیٹی) بلکہ (جن کو یہ لوگ اس کے بیٹے بیٹیاں سمجھتے ہیں) وہ اس کے عزت والے بندے ہیں','And they say, “The Most Compassionate has offspring!” Glory be to Him! In fact, those ˹angels˺ are only ˹His˺ honoured servants','और (अहले मक्का) कहते हैं कि खुदा ने (फरिश्तों को) अपनी औलाद (बेटियाँ) बना रखा है (हालाँकि) वह उससे पाक व पकीज़ा हैं बल्कि (वह फ़रिश्ते) (खुदा के) मोअज्ज़ि बन्दे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,27,'Al-Anbiyaa','لَا يَسۡبِقُونَهُۥ بِٱلۡقَوۡلِ وَهُم بِأَمۡرِهِۦ يَعۡمَلُونَ','اس کے آگے بڑھ کر بول نہیں سکتے۔ اور اس کے حکم پر عمل کرتے ہیں','who do not speak until He has spoken, ˹only˺ acting at His command','ये लोग उसके सामने बढ़कर बोल नहीं सकते और ये लोग उसी के हुक्म पर चलते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,28,'Al-Anbiyaa','يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يَشۡفَعُونَ إِلَّا لِمَنِ ٱرۡتَضَىٰ وَهُم مِّنۡ خَشۡيَتِهِۦ مُشۡفِقُونَ','جو کچھ ان کے آگے ہوچکا ہے اور پیچھے ہوگا وہ سب سے واقف ہے اور وہ (اس کے پاس کسی کی) سفارش نہیں کرسکتے مگر اس شخص کی جس سے خدا خوش ہو اور وہ اس کی ہیبت سے ڈرتے رہتے ہیں','He ˹fully˺ knows what is ahead of them and what is behind them. They do not intercede except for whom He approves, and they tremble in awe of Him','जो कुछ उनके सामने है और जो कुछ उनके पीछे है (ग़रज़ सब कुछ) वह (खुदा) जानता है और ये लोग उस शख्स के सिवा जिससे खुदा राज़ी हो किसी की सिफारिश भी नहीं करते और ये लोग खुद उसके ख़ौफ से (हर वक्त) ड़रते रहते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,29,'Al-Anbiyaa','۞وَمَن يَقُلۡ مِنۡهُمۡ إِنِّيٓ إِلَٰهࣱ مِّن دُونِهِۦ فَذَٰلِكَ نَجۡزِيهِ جَهَنَّمَۚ كَذَٰلِكَ نَجۡزِي ٱلظَّٰلِمِينَ','اور جو شخص ان میں سے یہ کہے کہ خدا کے سوا میں معبود ہوں تو اسے ہم دوزخ کی سزا دیں گے اور ظالموں کو ہم ایسی ہی سزا دیا کرتے ہیں','Whoever of them were to say, “I am a god besides Him,” they would be rewarded with Hell by Us. This is how We reward the wrongdoers','और उनमें से जो कोई ये कह दे कि खुदा नहीं (बल्कि) मैं माबूद हूँ तो वह (मरदूद बारगाह हुआ) हम उसको जहन्नुम की सज़ा देंगे और सरकशों को हम ऐसी ही सज़ा देते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,30,'Al-Anbiyaa','أَوَلَمۡ يَرَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ كَانَتَا رَتۡقࣰ ا فَفَتَقۡنَٰهُمَاۖ وَجَعَلۡنَا مِنَ ٱلۡمَآءِ كُلَّ شَيۡءٍ حَيٍّۚ أَفَلَا يُؤۡمِنُونَ','کیا کافروں نے نہیں دیکھا کہ آسمان اور زمین دونوں ملے ہوئے تھے تو ہم نے جدا جدا کردیا۔ اور تمام جاندار چیزیں ہم نے پانی سے بنائیں۔ پھر یہ لوگ ایمان کیوں نہیں لاتے؟','Do the disbelievers not realize that the heavens and earth were ˹once˺ one mass then We split them apart? And We created from water every living thing. Will they not then believe','जो लोग काफिर हो बैठे क्या उन लोगों ने इस बात पर ग़ौर नहीं किया कि आसमान और ज़मीन दोनों बस्ता (बन्द) थे तो हमने दोनों को शिगाफ़ता किया (खोल दिया) और हम ही ने जानदार चीज़ को पानी से पैदा किया इस पर भी ये लोग ईमान न लाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,31,'Al-Anbiyaa','وَجَعَلۡنَا فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِهِمۡ وَجَعَلۡنَا فِيهَا فِجَاجࣰ ا سُبُلࣰ ا لَّعَلَّهُمۡ يَهۡتَدُونَ','اور ہم نے زمین میں پہاڑ بنائے تاکہ لوگوں (کے بوجھ) سے ہلنے (اور جھکنے) نہ لگے اور اس میں کشادہ راستے بنائے تاکہ لوگ ان پر چلیں','And We have placed firm mountains upon the earth so it does not shake with them, and made in it broad pathways so they may find their way','और हम ही ने ज़मीन पर भारी बोझल पहाड़ बनाए ताकि ज़मीन उन लोगों को लेकर किसी तरफ झुक न पड़े और हम ने ही उसमें लम्बे-चौड़े रास्ते बनाए ताकि ये लोग अपने-अपने मंज़िलें मक़सूद को जा पहुँचे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,32,'Al-Anbiyaa','وَجَعَلۡنَا ٱلسَّمَآءَ سَقۡفࣰ ا مَّحۡفُوظࣰ اۖ وَهُمۡ عَنۡ ءَايَٰتِهَا مُعۡرِضُونَ','اور آسمان کو محفوظ چھت بنایا۔ اس پر بھی وہ ہماری نشانیوں سے منہ پھیر رہے ہیں','And We have made the sky a well-protected canopy, still they turn away from its signs','और हम ही ने आसमान को छत बनाया जो हर तरह महफूज़ है और ये लोग उसकी आसमानी निशानियों से मुँह फेर रहे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,33,'Al-Anbiyaa','وَهُوَ ٱلَّذِي خَلَقَ ٱلَّيۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ فِي فَلَكࣲ يَسۡبَحُونَ','اور وہی تو ہے جس نے رات اور دن اور سورج اور چاند کو بنایا۔ (یہ) سب (یعنی سورج اور چاند اور ستارے) آسمان میں (اس طرح چلتے ہیں گویا) تیر رہے ہیں','And He is the One Who created the day and the night, the sun and the moon—each travelling in an orbit','और वही वह (क़ादिरे मुत्तलिक़) है जिसने रात और दिन और आफ़ताब और माहताब को पैदा किया कि सब के सब एक (एक) आसमान में पैर कर चक्मर लगा रहे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,34,'Al-Anbiyaa','وَمَا جَعَلۡنَا لِبَشَرࣲ مِّن قَبۡلِكَ ٱلۡخُلۡدَۖ أَفَإِيْن مِّتَّ فَهُمُ ٱلۡخَٰلِدُونَ','اور (اے پیغمبر) ہم نے تم سے پہلے کسی آدمی کو بقائے دوام نہیں بخشا۔ بھلا اگر تم مرجاؤ تو کیا یہ لوگ ہمیشہ رہیں گے','We have not granted immortality to any human before you ˹O Prophet˺: so if you die, will they live forever','और (ऐ रसूल) हमने तुमसे पहले भी किसी फ़र्दे बशर को सदा की ज़िन्दगी नहीं दी तो क्या अगर तुम मर जाओगे तो ये लोग हमेशा जिया ही करेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,35,'Al-Anbiyaa','كُلُّ نَفۡسࣲ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَنَبۡلُوكُم بِٱلشَّرِّ وَٱلۡخَيۡرِ فِتۡنَةࣰۖ وَإِلَيۡنَا تُرۡجَعُونَ','ہر متنفس کو موت کا مزا چکھنا ہے۔ اور ہم تو لوگوں کو سختی اور آسودگی میں آزمائش کے طور پر مبتلا کرتے ہیں۔ اور تم ہماری طرف ہی لوٹ کر آؤ گے','Every soul will taste death. And We test you ˹O humanity˺ with good and evil as a trial, then to Us you will ˹all˺ be returned','(हर शख्स एक न एक दिन) मौत का मज़ा चखने वाला है और हम तुम्हें मुसीबत व राहत में इम्तिहान की ग़रज़ से आज़माते हैं और (आख़िकार) हमारी ही तरफ लौटाए जाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,36,'Al-Anbiyaa','وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓاْ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِي يَذۡكُرُ ءَالِهَتَكُمۡ وَهُم بِذِكۡرِ ٱلرَّحۡمَٰنِ هُمۡ كَٰفِرُونَ','اور جب کافر تم کو دیکھتے ہیں تو تم سے استہزاء کرتے ہیں کہ کیا یہی شخص ہے جو تمہارے معبودوں کا ذکر (برائی سے) کیا کرتا ہے حالانکہ وہ خود رحمٰن کے نام سے منکر ہیں','When the disbelievers see you ˹O Prophet˺, they only make fun of you, ˹saying,˺ “Is this the one who speaks ˹ill˺ of your gods?” while they disbelieve at the mention of the Most Compassionate','और (ऐ रसूल) जब तुम्हें कुफ्फ़ार देखते हैं तो बस तुमसे मसखरापन करते हैं कि क्या यही हज़रत हैं जो तुम्हारे माबूदों को (बुरी तरह) याद करते हैं हालाँकि ये लोग खुद खुदा की याद से इन्कार करते हैं (तो इनकी बेवकूफ़ी पर हँसना चाहिए)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,37,'Al-Anbiyaa','خُلِقَ ٱلۡإِنسَٰنُ مِنۡ عَجَلࣲۚ سَأُوْرِيكُمۡ ءَايَٰتِي فَلَا تَسۡتَعۡجِلُونِ','انسان (کچھ ایسا جلد باز ہے کہ گویا) جلد بازی ہی سے بنایا گیا ہے۔ میں تم لوگوں کو عنقریب اپنی نشانیاں دکھاؤں گا تو تم جلدی نہ کرو','Humankind is made of haste. I will soon show you My signs, so do not ask Me to hasten them','आदमी तो बड़ा जल्दबाज़ पैदा किया गया है मैं अनक़रीब ही तुम्हें अपनी (कुदरत की) निशानियाँ दिखाऊँगा तो तुम मुझसे जल्दी की (द्दूम) न मचाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,38,'Al-Anbiyaa','وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ','اور کہتے ہیں کہ اگر تم سچے ہو تو (جس عذاب کا) یہ وعید (ہے وہ) کب (آئے گا)؟','They ask ˹the believers˺, “When will this threat come to pass if what you say is true?”','और लुत्फ़ तो ये है कि कहते हैं कि अगर सच्चे हो तो ये क़यामत का वायदा कब (पूरा) होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,39,'Al-Anbiyaa','لَوۡ يَعۡلَمُ ٱلَّذِينَ كَفَرُواْ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمۡ وَلَا هُمۡ يُنصَرُونَ','اے کاش کافر اس وقت کو جانیں جب وہ اپنے مونہوں پر سے (دوزخ کی) آگ کو روک نہ سکیں گے اور نہ اپنی پیٹھوں پر سے اور نہ ان کا کوئی مددگار ہوگا','If only the disbelievers knew that a time will come when they will not be able to keep the Fire off their faces or backs, nor will they be helped','और जो लोग काफ़िर हो बैठे काश उस वक्त क़ी हालत से आगाह होते (कि जहन्नुम की आग में खडे होंगे) और न अपने चेहरों से आग को हटा सकेंगे और न अपनी पीठ से और न उनकी मदद की जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,40,'Al-Anbiyaa','بَلۡ تَأۡتِيهِم بَغۡتَةࣰ فَتَبۡهَتُهُمۡ فَلَا يَسۡتَطِيعُونَ رَدَّهَا وَلَا هُمۡ يُنظَرُونَ','بلکہ قیامت ان پر ناگہاں آ واقع ہوگی۔ اور ان کے ہوش کھو دے گی۔ پھر نہ تو وہ اس کو ہٹا سکیں گے اور نہ ان کو مہلت دی جائے گی','In fact, the Hour will take them by surprise, leaving them stunned. So they will not be able to avert it, nor will it be delayed from them','(क़यामत कुछ जता कर तो आने से रही) बल्कि वह तो अचानक उन पर आ पड़ेगी और उन्हें हक्का बक्का कर देगी फिर उस वक्त उसमें न उसके हटाने की मजाल होगी और न उन्हें ही दी जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,41,'Al-Anbiyaa','وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلࣲ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ','اور تم سے پہلے بھی پیغمبروں کے ساتھ استہزاء ہوتا رہا ہے تو جو لوگ ان میں سے تمسخر کیا کرتے تھے ان کو اسی (عذاب) نے جس کی ہنسی اُڑاتے تھے آگھیرا','˹Other˺ messengers had already been ridiculed before you ˹O Prophet˺, but those who mocked them were overtaken by what they used to ridicule','और (ऐ रसूल) कुछ तुम ही नहीं तुमसे पहले पैग़म्बरों के साथ मसख़रापन किया जा चुका है तो उन पैग़म्बरों से मसखरापन करने वालों को उस सख्त अज़ाब ने आ घेर लिया जिसकी वह हँसी उड़ाया करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,42,'Al-Anbiyaa','قُلۡ مَن يَكۡلَؤُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ مِنَ ٱلرَّحۡمَٰنِۚ بَلۡ هُمۡ عَن ذِكۡرِ رَبِّهِم مُّعۡرِضُونَ','کہو کہ رات اور دن میں خدا سے تمہاری کون حفاظت کرسکتا ہے؟ بات یہ ہے کہ اپنے پروردگار کی یاد سے منہ پھیرے ہوئے ہیں','Ask ˹them, O Prophet,˺ “Who can defend you by day or by night against the Most Compassionate?” Still they turn away from the remembrance of their Lord','(ऐ रसूल) तुम उनसे पूछो तो कि खुदा (के अज़ाब) से (बचाने में) रात को या दिन को तुम्हारा कौन पहरा दे सकता है उस पर डरना तो दर किनार बल्कि ये लोग अपने परवरदिगार की याद से मुँह फेरते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,43,'Al-Anbiyaa','أَمۡ لَهُمۡ ءَالِهَةࣱ تَمۡنَعُهُم مِّن دُونِنَاۚ لَا يَسۡتَطِيعُونَ نَصۡرَ أَنفُسِهِمۡ وَلَا هُم مِّنَّا يُصۡحَبُونَ','کیا ہمارے سوا ان کے اور معبود ہیں کہ ان کو (مصائب سے) بچاسکیں۔ وہ آپ اپنی مدد تو کر ہی نہیں سکتے اور نہ ہم سے پناہ ہی دیئے جائیں گے','Or do they have gods—other than Us—that can protect them? They cannot ˹even˺ protect themselves, nor will they be aided against Us','क्या हमरो सिवा उनके कुछ और परवरदिगार हैं कि जो उनको (हमारे अज़ाब से) बचा सकते हैं (वह क्या बचाएँगे) ये लोग खुद अपनी आप तो मदद कर ही नहीं सकते और न हमारे अज़ाब से उन्हें पनाह दी जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,44,'Al-Anbiyaa','بَلۡ مَتَّعۡنَا هَٰٓؤُلَآءِ وَءَابَآءَهُمۡ حَتَّىٰ طَالَ عَلَيۡهِمُ ٱلۡعُمُرُۗ أَفَلَا يَرَوۡنَ أَنَّا نَأۡتِي ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَآۚ أَفَهُمُ ٱلۡغَٰلِبُونَ','بلکہ ہم ان لوگوں کو اور ان کے باپ دادا کو متمتع کرتے رہے یہاں تک کہ (اسی حالت میں) ان کی عمریں بسر ہوگئیں۔ کیا یہ نہیں دیکھتے کہ ہم زمین کو اس کے کناروں سے گھٹاتے چلے آتے ہیں۔ تو کیا یہ لوگ غلبہ پانے والے ہیں؟','In fact, We have allowed enjoyment for these ˹Meccans˺ and their forefathers for such a long time ˹that they took it for granted˺. Do they not see that We gradually reduce ˹their˺ land from its borders? Is it they who will then prevail','बल्कि हम ही ने उनको और उनके बुर्जुग़ों को आराम व चैन रहा यहाँ तक कि उनकी उम्रें बढ़ गई तो फिर क्या ये लोग नहीं देखते कि हम रूए ज़मीन को चारों तरफ से क़ब्ज़ा करते और उसको फतेह करते चले आते हैं तो क्या (अब भी यही लोग कुफ्फ़ारे मक्का) ग़ालिब और वर हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,45,'Al-Anbiyaa','قُلۡ إِنَّمَآ أُنذِرُكُم بِٱلۡوَحۡيِۚ وَلَا يَسۡمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ','کہہ دو کہ میں تم کو حکم خدا کے مطابق نصیحت کرتا ہوں۔ اور بہروں کوجب نصیحت کی جائے تو وہ پکار کر سنتے ہی نہیں','Say, ˹O Prophet,˺ “I warn you only by revelation.” But the deaf cannot hear the call when they are warned','(ऐ रसूल) तुम कह दो कि मैं तो बस तुम लोगों को ''''वही'''' के मुताबिक़ (अज़ाब से) डराता हूँ (मगर तुम लोग गोया बहरे हो) और बहरों को जब डराया जाता है तो वह पुकारने ही को नहीं सुनते (डरें क्या ख़ाक)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,46,'Al-Anbiyaa','وَلَئِن مَّسَّتۡهُمۡ نَفۡحَةࣱ مِّنۡ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ','اور اگر ان کو تمہارے پروردگار کا تھوڑا سا عذاب بھی پہنچے تو کہنے لگیں کہ ہائے کم بختی ہم بےشک ستمگار تھے','If they were touched by even a breath of your Lord’s torment, they would certainly cry, “Woe to us! We have really been wrongdoers.”','और (ऐ रसूल) अगर कहीं उनको तुम्हारे परवरदिगार के अज़ाब की ज़रा सी हवा भी लग गई तो वे सख्त! बोल उठे हाय अफसोस वाक़ई हम ही ज़ालिम थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,47,'Al-Anbiyaa','وَنَضَعُ ٱلۡمَوَٰزِينَ ٱلۡقِسۡطَ لِيَوۡمِ ٱلۡقِيَٰمَةِ فَلَا تُظۡلَمُ نَفۡسࣱ شَيۡـࣰٔ اۖ وَإِن كَانَ مِثۡقَالَ حَبَّةࣲ مِّنۡ خَرۡدَلٍ أَتَيۡنَا بِهَاۗ وَكَفَىٰ بِنَا حَٰسِبِينَ','اور ہم قیامت کے دن انصاف کی ترازو کھڑی کریں گے تو کسی شخص کی ذرا بھی حق تلفی نہ کی جائے گی۔ اور اگر رائی کے دانے کے برابر بھی (کسی کا عمل) ہوگا تو ہم اس کو لاحاضر کریں گے۔ اور ہم حساب کرنے کو کافی ہیں','We will set up the scales of justice on the Day of Judgment, so no soul will be wronged in the least. And ˹even˺ if a deed is the weight of a mustard seed, We will bring it forth. And sufficient are We as a ˹vigilant˺ Reckoner','और क़यामत के दिन तो हम (बन्दों के भले बुरे आमाल तौलने के लिए) इन्साफ़ की तराज़ू में खड़ी कर देंगे तो फिर किसी शख्स पर कुछ भी ज़ुल्म न किया जाएगा और अगर राई के दाने के बराबर भी किसी का (अमल) होगा तो तुम उसे ला हाज़िर करेंगे और हम हिसाब करने के वास्ते बहुत काफ़ी हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,48,'Al-Anbiyaa','وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ وَهَٰرُونَ ٱلۡفُرۡقَانَ وَضِيَآءࣰ وَذِكۡرࣰ ا لِّلۡمُتَّقِينَ','اور ہم نے موسیٰ اور ہارون کو (ہدایت اور گمراہی میں) فرق کر دینے والی اور (سرتاپا) روشنی اور نصیحت (کی کتاب) عطا کی (یعنی) پرہیز گاروں کے لئے','Indeed, We granted Moses and Aaron the standard ˹to distinguish between right and wrong˺—a light and a reminder for the righteous','और हम ही ने यक़ीनन मूसा और हारून को (हक़ व बातिल की) जुदा करने वाली किताब (तौरेत) और परहेज़गारों के लिए अज़सरतापा बनूँ और नसीहत अता की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,49,'Al-Anbiyaa','ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشۡفِقُونَ','جو بن دیکھے اپنے پروردگار سے ڈرتے ہیں اور قیامت کا بھی خوف رکھتے ہیں','who are in awe of their Lord without seeing Him, and are fearful of the Hour','जो बे देखे अपने परवरदिगार से ख़ौफ खाते हैं और ये लोग रोज़े क़यामत से भी डरते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,50,'Al-Anbiyaa','وَهَٰذَا ذِكۡرࣱ مُّبَارَكٌ أَنزَلۡنَٰهُۚ أَفَأَنتُمۡ لَهُۥ مُنكِرُونَ','یہ مبارک نصیحت ہے جسے ہم نے نازل فرمایا ہے تو کیا تم اس سے انکار کرتے ہو؟','And this ˹Quran˺ is a blessed reminder which We have revealed. Will you ˹pagans˺ then deny it','और ये (कुरान भी) एक बाबरकत तज़किरा है जिसको हमने उतारा है तो क्या तुम लोग इसको नहीं मानते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,51,'Al-Anbiyaa','۞وَلَقَدۡ ءَاتَيۡنَآ إِبۡرَٰهِيمَ رُشۡدَهُۥ مِن قَبۡلُ وَكُنَّا بِهِۦ عَٰلِمِينَ','اور ہم نے ابراہیمؑ کو پہلے ہی سے ہدایت دی تھی اور ہم ان کے حال سے واقف تھے','And indeed, We had granted Abraham sound judgment early on, for We knew him well ˹to be worthy of it˺','और इसमें भी शक नहीं कि हमने इबराहीम को पहले ही से फ़हेम सलीम अता की थी और हम उन (की हालत) से खूब वाक़िफ थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,52,'Al-Anbiyaa','إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِيٓ أَنتُمۡ لَهَا عَٰكِفُونَ','جب انہوں نے اپنے باپ اور اپنی قوم کے لوگوں سے کہا یہ کیا مورتیں ہیں جن (کی پرستش) پر تم معتکف (وقائم) ہو؟','˹Remember˺ when he questioned his father and his people, “What are these statues to which you are so devoted?”','जब उन्होंने अपने (मुँह बोले) बाप और अपनी क़ौम से कहा ये मूर्ते जिनकी तुम लोग मुजाबिरी करते हो आख़िर क्या (बला) है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,53,'Al-Anbiyaa','قَالُواْ وَجَدۡنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ','وہ کہنے لگے کہ ہم نے اپنے باپ دادا کو ان کی پرستش کرتے دیکھا ہے','They replied, “We found our forefathers worshipping them.”','वह लोग बोले (और तो कुछ नहीं जानते मगर) अपने बडे बूढ़ों को इनही की परसतिश करते देखा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,54,'Al-Anbiyaa','قَالَ لَقَدۡ كُنتُمۡ أَنتُمۡ وَءَابَآؤُكُمۡ فِي ضَلَٰلࣲ مُّبِينࣲ‏','(ابراہیم نے) کہا کہ تم بھی (گمراہ ہو) اور تمہارے باپ دادا بھی صریح گمراہی میں پڑے رہے','He responded, “Indeed, you and your forefathers have been clearly astray.”','इबराहीम ने कहा यक़ीनन तुम भी और तुम्हारे बुर्जुग़ भी खुली हुईगुमराही में पड़े हुए थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,55,'Al-Anbiyaa','قَالُوٓاْ أَجِئۡتَنَا بِٱلۡحَقِّ أَمۡ أَنتَ مِنَ ٱللَّٰعِبِينَ','وہ بولے کیا تم ہمارے پاس (واقعی) حق لائے ہو یا (ہم سے) کھیل (کی باتیں) کرتے ہو؟','They asked, “Have you come to us with the truth, or is this a joke?”','वह लोग कहने लगे तो क्या तुम हमारे पास हक़ बात लेकर आए हो या तुम भी (यूँ ही) दिल्लगी करते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,56,'Al-Anbiyaa','قَالَ بَل رَّبُّكُمۡ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلَّذِي فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّٰهِدِينَ','(ابراہیم نے) کہا (نہیں) بلکہ تمہارا پروردگار آسمانوں اور زمین کا پروردگار ہے جس نے ان کو پیدا کیا ہے۔ اور میں اس (بات) کا گواہ (اور اسی کا قائل) ہوں','He replied, “In fact, your Lord is the Lord of the heavens and the earth, Who created them ˹both˺. And to that I bear witness.”','इबराहीम ने कहा मज़ाक नहीं ठीक कहता हूँ कि तुम्हारे माबूद व बुत नहीं बल्कि तुम्हारा परवरदिगार आसमान व ज़मीन का मालिक है जिसने उनको पैदा किया और मैं खुद इस बात का तुम्हारे सामने गवाह हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,57,'Al-Anbiyaa','وَتَٱللَّهِ لَأَكِيدَنَّ أَصۡنَٰمَكُم بَعۡدَ أَن تُوَلُّواْ مُدۡبِرِينَ','اور خدا کی قسم جب تم پیٹھ پھیر کر چلے جاؤ گے تو میں تمہارے بتوں سے ایک چال چلوں گا','˹Then he said to himself,˺ “By Allah! I will surely plot against your idols after you have turned your backs and gone away.”','और अपने जी में कहा खुदा की क़सम तुम्हारे पीठ फेरने के बाद में तुम्हारे बुतों के साथ एक चाल चलूँगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,58,'Al-Anbiyaa','فَجَعَلَهُمۡ جُذَٰذًا إِلَّا كَبِيرࣰ ا لَّهُمۡ لَعَلَّهُمۡ إِلَيۡهِ يَرۡجِعُونَ','پھر ان کو توڑ کر ریزہ ریزہ کردیا مگر ایک بڑے (بت) کو (نہ توڑا) تاکہ وہ اس کی طرف رجوع کریں','So he smashed them into pieces, except the biggest of them, so they might turn to it ˹for answers˺','चुनान्चे इबराहीम ने उन बुतों को (तोड़कर) चकनाचूर कर डाला मगर उनके बड़े बुत को (इसलिए रहने दिया) ताकि ये लोग ईद से पलटकर उसकी तरफ रूजू करें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,59,'Al-Anbiyaa','قَالُواْ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ','کہنے لگے کہ ہمارے معبودوں کے ساتھ یہ معاملہ کس نے کیا؟ وہ تو کوئی ظالم ہے','They protested, “Who dared do this to our gods? It must be an evildoer!”','(जब कुफ्फ़ार को मालूम हुआ) तो कहने लगे जिसने ये गुस्ताख़ी हमारे माबूदों के साथ की है उसने यक़ीनी बड़ा ज़ुल्म किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,60,'Al-Anbiyaa','قَالُواْ سَمِعۡنَا فَتࣰ ى يَذۡكُرُهُمۡ يُقَالُ لَهُۥٓ إِبۡرَٰهِيمُ','لوگوں نے کہا کہ ہم نے ایک جوان کو ان کا ذکر کرتے ہوئے سنا ہے اس کو ابراہیم کہتے ہیں','Some said, “We heard a young man, called Abraham, speaking ˹ill˺ of them.”','(कुछ लोग) कहने लगे हमने एक नौजवान को जिसको लोग इबराहीम कहते हैं उन बुतों का (बुरी तरह) ज़िक्र करते सुना था');
